/**
 * Import system orchestrator.
 * Routes files to the correct parser based on extension.
 */

import type { ImportDetection } from '../types';
import { parseSpreadsheet } from './parsers/spreadsheet';
import { parseDocument } from './parsers/document';
import { parseImage } from './parsers/image';

const SPREADSHEET_EXTS = ['xlsx', 'csv', 'xls'];
const DOCUMENT_EXTS = ['pdf', 'docx', 'doc'];
const IMAGE_EXTS = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'svg'];

const ACCEPTED_EXTENSIONS = [...SPREADSHEET_EXTS, ...DOCUMENT_EXTS, ...IMAGE_EXTS];

const ACCEPTED_MIME_TYPES = [
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.ms-excel',
  'text/csv',
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/msword',
  'image/png',
  'image/jpeg',
  'image/gif',
  'image/webp',
  'image/bmp',
  'image/svg+xml',
];

export const ACCEPTED_EXTENSIONS_STRING = ACCEPTED_EXTENSIONS.map(e => `.${e}`).join(',');

function getFileExtension(filename: string): string {
  return (filename.split('.').pop() || '').toLowerCase();
}

/**
 * Check if a file has a supported extension.
 */
export function isFileSupported(file: File): boolean {
  const ext = getFileExtension(file.name);
  return ACCEPTED_EXTENSIONS.includes(ext);
}

/**
 * Process a batch of files through the import pipeline.
 * Returns an ImportDetection for each file.
 */
export async function processImportFiles(
  files: File[],
  onProgress?: (current: number, total: number, filename: string) => void
): Promise<ImportDetection[]> {
  const results: ImportDetection[] = [];

  for (let i = 0; i < files.length; i++) {
    const file = files[i];
    onProgress?.(i + 1, files.length, file.name);

    if (!isFileSupported(file)) {
      results.push({
        file,
        fileType: 'document',
        detectedEntity: 'unknown',
        confidence: 0,
        preview: {
          summary: `Unsupported file type: .${getFileExtension(file.name)}`,
        },
      });
      continue;
    }

    try {
      const ext = getFileExtension(file.name);

      if (SPREADSHEET_EXTS.includes(ext)) {
        results.push(await parseSpreadsheet(file));
      } else if (DOCUMENT_EXTS.includes(ext)) {
        results.push(await parseDocument(file));
      } else if (IMAGE_EXTS.includes(ext)) {
        results.push(await parseImage(file));
      }
    } catch (err) {
      results.push({
        file,
        fileType: 'document',
        detectedEntity: 'unknown',
        confidence: 0,
        preview: {
          summary: `Error processing ${file.name}: ${err instanceof Error ? err.message : 'Unknown error'}`,
        },
      });
    }
  }

  return results;
}

/**
 * Filter files from a drag event's DataTransfer.
 */
function extractFilesFromDrop(e: DragEvent): File[] {
  const files: File[] = [];
  if (e.dataTransfer?.files) {
    for (let i = 0; i < e.dataTransfer.files.length; i++) {
      files.push(e.dataTransfer.files[i]);
    }
  }
  return files;
}

import type { RecurringInvoice, Invoice, Expense, Project, Milestone } from '../types';

const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export interface ForecastMonth {
  label: string;
  key: string;
}

export interface RevenueForecastItem {
  month: ForecastMonth;
  confirmed: number;
  probable: number;
  projected: number;
  baseline: number;
}

export interface ExpenseForecastItem {
  month: ForecastMonth;
  known: number;
  projected: number;
  baseline: number;
}

export interface CashFlowItem {
  month: ForecastMonth;
  income: number;
  expenses: number;
  net: number;
  runningBalance?: number;
}

export interface ScenarioParams {
  newClientsPerMonth: number;
  rateIncrease: number;
  expenseGrowth: number;
  mode: 'optimistic' | 'base' | 'conservative';
}

export interface ForecastMetrics {
  projectedNextMonth: number;
  projectedNextQuarter: number;
  revenueCertainty: number;
  monthsOfRunway: number | null;
}

export function getNextMonths(count: number): ForecastMonth[] {
  const now = new Date();
  const months: ForecastMonth[] = [];
  for (let i = 0; i < count; i++) {
    const d = new Date(now.getFullYear(), now.getMonth() + i, 1);
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    const label = `${MONTH_NAMES[d.getMonth()]} ${d.getFullYear()}`;
    months.push({ label, key });
  }
  return months;
}

export function getMonthKey(date: Date): string {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
}

export function monthDiff(a: string, b: string): number {
  const [ay, am] = a.split('-').map(Number);
  const [by, bm] = b.split('-').map(Number);
  return (ay - by) * 12 + (am - bm);
}

function frequencyMonths(freq: string): number {
  switch (freq) {
    case 'weekly': return 1 / 4;
    case 'biweekly': return 0.5;
    case 'monthly': return 1;
    case 'quarterly': return 3;
    default: return 1;
  }
}

function occurrencesInMonth(sourceKey: string, freqMonths: number, monthKey: string): number {
  const diff = monthDiff(monthKey, sourceKey);
  if (diff < 0) return 0;

  const kMin = Math.ceil(diff / freqMonths);
  const kMax = Math.ceil((diff + 1) / freqMonths) - 1;
  return Math.max(0, kMax - kMin + 1);
}

function computeRecurringInvoicesByMonth(
  recurringInvoices: RecurringInvoice[],
  forecastMonths: ForecastMonth[],
  thisMonthKey: string,
): Record<string, number> {
  const result: Record<string, number> = {};
  const active = recurringInvoices.filter((r) => r.active);

  for (const ri of active) {
    const freqMonths = frequencyMonths(ri.frequency);
    const startKey = ri.next_due ? ri.next_due.substring(0, 7) : thisMonthKey;

    for (const fm of forecastMonths) {
      if (fm.key < startKey) continue;
      const occurs = occurrencesInMonth(startKey, freqMonths, fm.key);
      if (occurs > 0) {
        result[fm.key] = (result[fm.key] || 0) + ri.total * occurs;
      }
    }
  }

  return result;
}

function computeMilestoneInvoicesByMonth(
  projects: Project[],
  milestonesByProject: Record<string, Milestone[]>,
  forecastMonths: ForecastMonth[],
): Record<string, number> {
  const result: Record<string, number> = {};

  for (const project of projects) {
    if (project.status !== 'active' || !project.budget) continue;

    const milestones = milestonesByProject[project.id] || [];
    const invoiceMilestones = milestones.filter(
      (m) => m.invoice_on_completion && m.due_date,
    );

    if (invoiceMilestones.length > 0) {
      const sharePerMilestone = project.budget / invoiceMilestones.length;
      for (const ms of invoiceMilestones) {
        const msMonth = ms.due_date!.substring(0, 7);
        for (const fm of forecastMonths) {
          if (fm.key === msMonth) {
            result[fm.key] = (result[fm.key] || 0) + sharePerMilestone;
          }
        }
      }
    } else if (project.end_date) {
      const startKey = project.start_date
        ? project.start_date.substring(0, 7)
        : thisMonthKeyFromMonths(forecastMonths);
      const endKey = project.end_date.substring(0, 7);
      const totalMonths = monthDiff(endKey, startKey) + 1;
      if (totalMonths > 0) {
        const perMonth = project.budget / totalMonths;
        for (const fm of forecastMonths) {
          if (fm.key >= startKey && fm.key <= endKey) {
            result[fm.key] = (result[fm.key] || 0) + perMonth;
          }
        }
      }
    }
  }

  return result;
}

function thisMonthKeyFromMonths(forecastMonths: ForecastMonth[]): string {
  if (forecastMonths.length > 0) return forecastMonths[0].key;
  return getMonthKey(new Date());
}

function computeSentInvoicesByMonth(
  invoices: Invoice[],
  forecastMonths: ForecastMonth[],
): Record<string, number> {
  const result: Record<string, number> = {};
  const sent = invoices.filter((i) => i.status === 'sent' && i.due_date);

  for (const inv of sent) {
    const invMonth = inv.due_date!.substring(0, 7);
    for (const fm of forecastMonths) {
      if (fm.key === invMonth) {
        result[fm.key] = (result[fm.key] || 0) + inv.total;
      }
    }
  }

  return result;
}

export function computeAvgMonthlyPaid(
  monthlyPaid: Record<string, number>,
): number {
  const months = Object.keys(monthlyPaid).sort().reverse().slice(0, 3);
  if (months.length === 0) return 0;
  return months.reduce((sum, m) => sum + monthlyPaid[m], 0) / months.length;
}

export function computeAvgMonthlyExpenses(
  monthlyExpenses: Record<string, number>,
): number {
  const months = Object.keys(monthlyExpenses).sort().reverse().slice(0, 3);
  if (months.length === 0) return 0;
  return months.reduce((sum, m) => sum + monthlyExpenses[m], 0) / months.length;
}

export function computeAvgClientRevenue(
  invoices: Invoice[],
): number {
  const paid = invoices.filter((i) => i.status === 'paid');
  if (paid.length === 0) return 0;
  const uniqueClients = new Set(paid.map((i) => i.client_id));
  if (uniqueClients.size === 0) return 0;
  const totalPaid = paid.reduce((sum, i) => sum + i.total, 0);
  return totalPaid / uniqueClients.size;
}

export function computeRevenueForecast(
  recurringInvoices: RecurringInvoice[],
  invoices: Invoice[],
  projects: Project[],
  milestonesByProject: Record<string, Milestone[]>,
  monthlyPaid: Record<string, number>,
  forecastMonths: ForecastMonth[],
): RevenueForecastItem[] {
  const thisMonth = forecastMonths.length > 0 ? forecastMonths[0].key : getMonthKey(new Date());

  const recurring = computeRecurringInvoicesByMonth(recurringInvoices, forecastMonths, thisMonth);
  const milestone = computeMilestoneInvoicesByMonth(projects, milestonesByProject, forecastMonths);
  const sent = computeSentInvoicesByMonth(invoices, forecastMonths);
  const baseline = computeAvgMonthlyPaid(monthlyPaid);

  return forecastMonths.map((m) => {
    const confirmed = Math.round((recurring[m.key] || 0) + (milestone[m.key] || 0));
    const probable = Math.round(sent[m.key] || 0);
    const totalCommitted = confirmed + probable;
    const projected = Math.max(0, Math.round(baseline - totalCommitted));
    return {
      month: m,
      confirmed,
      probable,
      projected,
      baseline: Math.round(baseline),
    };
  });
}

export function computeExpenseForecast(
  expenses: Expense[],
  monthlyExpenses: Record<string, number>,
  forecastMonths: ForecastMonth[],
): ExpenseForecastItem[] {
  const thisMonth = forecastMonths.length > 0 ? forecastMonths[0].key : getMonthKey(new Date());
  const baseline = computeAvgMonthlyExpenses(monthlyExpenses);

  const knownByMonth: Record<string, number> = {};

  const recurring = expenses.filter((e) => e.recurring);
  for (const exp of recurring) {
    const freq = exp.frequency || 'monthly';
    const freqMonths = frequencyMonths(freq);
    const startKey = exp.date.substring(0, 7);

    for (const fm of forecastMonths) {
      if (fm.key < startKey) continue;
      const occurs = occurrencesInMonth(startKey, freqMonths, fm.key);
      if (occurs > 0) {
        knownByMonth[fm.key] = (knownByMonth[fm.key] || 0) + exp.amount * occurs;
      }
    }
  }

  return forecastMonths.map((m) => {
    const known = Math.round(knownByMonth[m.key] || 0);
    const baselineRound = Math.round(baseline);
    const projected = Math.max(0, Math.round(baseline - known));
    return {
      month: m,
      known,
      projected,
      baseline: baselineRound,
    };
  });
}

export function computeCashFlow(
  revenueItems: RevenueForecastItem[],
  expenseItems: ExpenseForecastItem[],
  currentBalance?: number,
): CashFlowItem[] {
  let running = currentBalance ?? 0;

  return revenueItems.map((rev, i) => {
    const exp = expenseItems[i];
    const income = rev.confirmed + rev.probable + rev.projected;
    const expenses = exp.known + exp.projected;
    const net = income - expenses;
    running += net;
    return {
      month: rev.month,
      income,
      expenses,
      net,
      runningBalance: currentBalance !== undefined ? running : undefined,
    };
  });
}

export function applyScenario(
  revenueItems: RevenueForecastItem[],
  expenseItems: ExpenseForecastItem[],
  avgClientRevenue: number,
  params: ScenarioParams,
): { revenue: RevenueForecastItem[]; expenses: ExpenseForecastItem[] } {
  const modeMultiplier = params.mode === 'optimistic' ? 1.2 : params.mode === 'conservative' ? 0.8 : 1.0;
  const rateMultiplier = (1 + params.rateIncrease / 100) * modeMultiplier;
  const expenseMultiplier = 1 + params.expenseGrowth / 100;

  const newRevenue: RevenueForecastItem[] = revenueItems.map((item, i) => {
    if (i === 0) {
      return {
        ...item,
        confirmed: Math.round(item.confirmed * rateMultiplier),
        probable: Math.round(item.probable * rateMultiplier),
        projected: Math.round(item.projected * rateMultiplier),
        baseline: Math.round(item.baseline * rateMultiplier),
      };
    }
    const extraClients = Math.round(params.newClientsPerMonth * avgClientRevenue * rateMultiplier * i);
    return {
      ...item,
      confirmed: Math.round(item.confirmed * rateMultiplier) + extraClients,
      probable: Math.round(item.probable * rateMultiplier),
      projected: Math.round(item.projected * rateMultiplier),
      baseline: Math.round(item.baseline * rateMultiplier),
    };
  });

  const newExpenses: ExpenseForecastItem[] = expenseItems.map((item) => ({
    ...item,
    known: Math.round(item.known * expenseMultiplier),
    projected: Math.round(item.projected * expenseMultiplier),
    baseline: Math.round(item.baseline * expenseMultiplier),
  }));

  return { revenue: newRevenue, expenses: newExpenses };
}

export function computeForecastMetrics(
  revenueItems: RevenueForecastItem[],
  expenseItems: ExpenseForecastItem[],
  forecastMonths: ForecastMonth[],
  currentBalance?: number,
): ForecastMetrics {
  if (revenueItems.length === 0) {
    return {
      projectedNextMonth: 0,
      projectedNextQuarter: 0,
      revenueCertainty: 0,
      monthsOfRunway: currentBalance !== undefined ? null : null,
    };
  }

  const nextMonth = revenueItems[0];
  const projectedNextMonth = nextMonth.confirmed + nextMonth.probable + nextMonth.projected;

  const quarterItems = revenueItems.slice(0, 3);
  const projectedNextQuarter = quarterItems.reduce(
    (sum, item) => sum + item.confirmed + item.probable + item.projected,
    0,
  );

  const totalConfirmed = revenueItems.reduce((sum, item) => sum + item.confirmed, 0);
  const totalProjected = revenueItems.reduce(
    (sum, item) => sum + item.confirmed + item.probable + item.projected,
    0,
  );
  const revenueCertainty = totalProjected > 0 ? Math.round((totalConfirmed / totalProjected) * 100) : 0;

  let monthsOfRunway: number | null = null;
  if (currentBalance !== undefined && currentBalance > 0) {
    const cashFlowItems = computeCashFlow(revenueItems, expenseItems, currentBalance);
    let balance = currentBalance;
    let months = 0;
    for (const cf of cashFlowItems) {
      balance = cf.runningBalance!;
      if (balance <= 0) break;
      months++;
    }
    monthsOfRunway = months > 0 ? months : null;
  }

  return {
    projectedNextMonth,
    projectedNextQuarter,
    revenueCertainty,
    monthsOfRunway,
  };
}

import type { TimeEntry } from '../types';

const MONTHS_SHORT = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const DAY_NAMES_FULL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const DAY_NAMES_SHORT = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

export interface HeatmapCell {
  date: Date;
  hours: number;
  billableHours: number;
  entries: TimeEntry[];
}

export interface HourCell {
  dayOfWeek: number;
  hour: number;
  count: number;
}

export interface DOWBar {
  day: string;
  dayIndex: number;
  avgHours: number;
  totalHours: number;
  count: number;
}

export interface StreakStats {
  currentStreak: number;
  longestStreak: number;
  totalHoursThisYear: number;
  bestDayHours: number;
  bestDayDate: string;
  bestDayEntries: number;
  mostActiveMonth: string;
  mostActiveMonthHours: number;
  totalDays: number;
}

export interface MonthLabel {
  month: string;
  col: number;
  spans: number;
}

export function getDateKey(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

export function getIntensity(hours: number): number {
  if (hours <= 0) return 0;
  if (hours <= 1) return 1;
  if (hours <= 2) return 2;
  if (hours <= 4) return 3;
  if (hours <= 6) return 4;
  return 5;
}

export function getIntensityColor(hours: number): string {
  const level = getIntensity(hours);
  const accentVar = 'var(--accent)';
  const surfaceVar = 'var(--color-surface-2, var(--bg-secondary))';
  const opacity = [5, 20, 40, 60, 80, 100][level];
  return `color-mix(in srgb, ${accentVar} ${opacity}%, ${surfaceVar})`;
}

export function formatTooltip(cell: HeatmapCell): string {
  const d = cell.date;
  return `${DAY_NAMES_FULL[d.getDay()]} ${MONTHS_SHORT[d.getMonth()]} ${d.getDate()} — ${cell.hours.toFixed(1)}h logged (${cell.billableHours.toFixed(1)}h billable)`;
}

function getFirstSunday(year: number): Date {
  const d = new Date(year, 0, 1);
  while (d.getDay() !== 0) d.setDate(d.getDate() + 1);
  return d;
}

export function computeHeatmapGrid(
  timeEntries: TimeEntry[],
  year: number,
  projectId?: string,
): HeatmapCell[][] {
  const filtered = projectId
    ? timeEntries.filter((t) => t.project_id === projectId)
    : timeEntries;

  const minutesByDay: Record<string, { minutes: number; billableMinutes: number; entries: TimeEntry[] }> = {};
  for (const t of filtered) {
    const key = t.start_time.substring(0, 10);
    if (!minutesByDay[key]) minutesByDay[key] = { minutes: 0, billableMinutes: 0, entries: [] };
    minutesByDay[key].minutes += (t.duration_minutes || 0);
    if (t.billable) minutesByDay[key].billableMinutes += (t.duration_minutes || 0);
    minutesByDay[key].entries.push(t);
  }

  const startDate = getFirstSunday(year);
  const now = new Date();
  const endDate = new Date(year, 11, 31);
  const lastDate = endDate > now ? now : endDate;

  const totalDays = Math.ceil((lastDate.getTime() - startDate.getTime()) / 86400000) + 1;
  const numWeeks = Math.ceil(totalDays / 7);

  const grid: HeatmapCell[][] = [];
  for (let w = 0; w < numWeeks; w++) {
    const week: HeatmapCell[] = [];
    for (let d = 0; d < 7; d++) {
      const cellDate = new Date(startDate);
      cellDate.setDate(cellDate.getDate() + w * 7 + d);
      const key = getDateKey(cellDate);
      const day = minutesByDay[key];
      week.push({
        date: cellDate,
        hours: day ? day.minutes / 60 : 0,
        billableHours: day ? day.billableMinutes / 60 : 0,
        entries: day ? day.entries : [],
      });
    }
    grid.push(week);
  }

  return grid;
}

export function computeStreakStats(
  timeEntries: TimeEntry[],
  year: number,
): StreakStats {
  const minutesByDay: Record<string, { minutes: number; entries: number }> = {};
  for (const t of timeEntries) {
    const key = t.start_time.substring(0, 10);
    if (!minutesByDay[key]) minutesByDay[key] = { minutes: 0, entries: 0 };
    minutesByDay[key].minutes += (t.duration_minutes || 0);
    minutesByDay[key].entries += 1;
  }

  const sortedDates = Object.keys(minutesByDay)
    .filter((k) => minutesByDay[k].minutes > 0)
    .sort();

  let longestStreak = 0;
  let currentStreak = 0;
  let streak = 0;

  for (let i = 0; i < sortedDates.length; i++) {
    if (i === 0) {
      streak = 1;
    } else {
      const prev = new Date(sortedDates[i - 1]);
      const curr = new Date(sortedDates[i]);
      const diff = (curr.getTime() - prev.getTime()) / 86400000;
      if (diff <= 1.1) {
        streak++;
      } else {
        if (streak > longestStreak) longestStreak = streak;
        streak = 1;
      }
    }
    if (streak > longestStreak) longestStreak = streak;
  }

  const now = new Date();
  const checkDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  let cs = 0;
  for (let i = 0; i < 365; i++) {
    const key = getDateKey(checkDate);
    if (minutesByDay[key] && minutesByDay[key].minutes > 0) {
      cs++;
    } else {
      break;
    }
    checkDate.setDate(checkDate.getDate() - 1);
  }
  currentStreak = cs;

  const yearStart = new Date(year, 0, 1);
  let hoursThisYear = 0;
  for (const [key, day] of Object.entries(minutesByDay)) {
    if (new Date(key) >= yearStart) {
      hoursThisYear += day.minutes / 60;
    }
  }

  let bestDayHours = 0;
  let bestDayDate = '';
  let bestDayEntries = 0;
  for (const [key, day] of Object.entries(minutesByDay)) {
    if (day.minutes / 60 > bestDayHours) {
      bestDayHours = day.minutes / 60;
      bestDayDate = key;
      bestDayEntries = day.entries;
    }
  }

  const monthlyHours: Record<string, number> = {};
  for (const [key, day] of Object.entries(minutesByDay)) {
    const m = key.substring(0, 7);
    monthlyHours[m] = (monthlyHours[m] || 0) + day.minutes / 60;
  }
  let mostActiveMonth = '';
  let mostActiveMonthHours = 0;
  for (const [m, h] of Object.entries(monthlyHours)) {
    if (h > mostActiveMonthHours) {
      mostActiveMonthHours = h;
      mostActiveMonth = m;
    }
  }
  if (mostActiveMonth) {
    const [y, mo] = mostActiveMonth.split('-').map(Number);
    mostActiveMonth = `${MONTHS_SHORT[mo - 1]} ${y}`;
  }

  return {
    currentStreak: cs,
    longestStreak,
    totalHoursThisYear: hoursThisYear,
    bestDayHours,
    bestDayDate,
    bestDayEntries,
    mostActiveMonth,
    mostActiveMonthHours,
    totalDays: sortedDates.length,
  };
}

export function computeDayOfWeekBreakdown(
  timeEntries: TimeEntry[],
  projectId?: string,
): DOWBar[] {
  const filtered = projectId
    ? timeEntries.filter((t) => t.project_id === projectId)
    : timeEntries;

  const byDay: { minutes: number; count: number }[] = Array.from({ length: 7 }, () => ({ minutes: 0, count: 0 }));
  const seenDays = new Set<string>();

  for (const t of filtered) {
    const d = new Date(t.start_time);
    const day = d.getDay();
    byDay[day].minutes += (t.duration_minutes || 0);
    byDay[day].count += 1;
    seenDays.add(t.start_time.substring(0, 10));
  }

  const uniqueDays = seenDays.size || 1;
  const dowDays: Record<number, number> = {};
  for (const dk of seenDays) {
    const dw = new Date(dk).getDay();
    dowDays[dw] = (dowDays[dw] || 0) + 1;
  }

  return DAY_NAMES_SHORT.map((day, i) => ({
    day,
    dayIndex: i,
    avgHours: byDay[i].minutes / 60 / Math.max(dowDays[i] || 1, 1),
    totalHours: byDay[i].minutes / 60,
    count: byDay[i].count,
  }));
}

export function computeHourOfDayHeatmap(
  timeEntries: TimeEntry[],
  projectId?: string,
): HourCell[][] {
  const filtered = projectId
    ? timeEntries.filter((t) => t.project_id === projectId)
    : timeEntries;

  const grid: number[][] = Array.from({ length: 7 }, () => new Array(24).fill(0));

  for (const t of filtered) {
    const d = new Date(t.start_time);
    const day = d.getDay();
    const hour = d.getHours();
    grid[day][hour]++;
  }

  return grid.map((hours, dayOfWeek) =>
    hours.map((count, hour) => ({
      dayOfWeek,
      hour,
      count,
    })),
  );
}

export function getMaxHourCount(hourGrid: HourCell[][]): number {
  let max = 0;
  for (const row of hourGrid) {
    for (const cell of row) {
      if (cell.count > max) max = cell.count;
    }
  }
  return max;
}

export function computeMonthLabels(
  grid: HeatmapCell[][],
): MonthLabel[] {
  const labels: MonthLabel[] = [];
  let lastMonth = -1;

  for (let w = 0; w < grid.length; w++) {
    const cell = grid[w]?.[0];
    if (cell) {
      const m = cell.date.getMonth();
      if (m !== lastMonth) {
        lastMonth = m;
        labels.push({ month: MONTHS_SHORT[m], col: w, spans: 1 });
      } else if (labels.length > 0) {
        labels[labels.length - 1].spans++;
      }
    }
  }

  return labels;
}

export function computeProjectColor(
  projectId: string | undefined,
  projects: { id: string; color?: string }[],
  defaultColor: string = 'var(--accent)',
): string {
  if (!projectId) return defaultColor;
  const project = projects.find((p) => p.id === projectId);
  if (project?.color) {
    return project.color;
  }
  return defaultColor;
}

export function getHoursLabel(hours: number): string {
  if (hours >= 0.01 && hours < 1) return '0–1h';
  if (hours >= 1 && hours < 2) return '1–2h';
  if (hours >= 2 && hours < 4) return '2–4h';
  if (hours >= 4 && hours < 6) return '4–6h';
  if (hours >= 6) return '6h+';
  return '0h';
}

export function formatHourLabel(hour: number): string {
  const ampm = hour < 12 ? 'AM' : 'PM';
  const h = hour === 0 ? 12 : hour > 12 ? hour - 12 : hour;
  return `${h}${ampm}`;
}

