                          {!isLoaded ? (
                            <button
                              onClick={() => loadMetricValues(def.id)}
                              className="text-[10px] text-[var(--accent)] hover:underline"
                            >
                              Load history
                            </button>
                          ) : values.length === 0 ? (
                            <p className="text-[10px] text-[var(--text-tertiary)]">No values logged yet.</p>
