                                <input
                                  type={def.metric_type === 'text' ? 'text' : 'number'}
                                  value={valueForm.value}
                                  onChange={(e) => setValueForm({ ...valueForm, value: e.target.value })}
                                  placeholder={`Value${def.unit_label ? ` (${def.unit_label})` : ''}`}
