                                  onKeyDown={(e) => { if (e.key === 'Enter') handleLogValue(def.id); }}
                                  autoFocus
                                />
                              </div>
                              <div>
                                <input
                                  type="date"
                                  value={valueForm.period}
                                  onChange={(e) => setValueForm({ ...valueForm, period: e.target.value })}
