                                />
                              </div>
                              <Button size="sm" onClick={() => handleLogValue(def.id)}>Log</Button>
                              <button onClick={() => setShowValueForm(null)} className="p-1.5 text-[var(--text-tertiary)] hover:text-[var(--text-primary)]">
                                <X size={14} />
