];

const TEMPLATE_BADGE_COLORS: Record<string, string> = {
  General: 'info',
  Retainer: 'success',
  Legal: 'warning',
  IP: 'purple',
  Partnership: 'amber',
};

export default function Contracts() {
  const { contracts, loadContracts, clients, loadClients, addContract, updateContract, removeContract, contractTemplates, loadContractTemplates, addContractTemplate, removeContractTemplate } = useStore();
  const addToast = useToasts((s) => s.add);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState<Contract | null>(null);
  const [expanded, setExpanded] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState<{ id: string; title: string } | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [search, setSearch] = useState('');
  const [form, setForm] = useState({ client_id: '', title: '', body: '' });
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<'contracts' | 'templates'>('contracts');
  const [showTemplatesTab, setShowTemplatesTab] = useState(false);
  const [showTemplatePicker, setShowTemplatePicker] = useState(false);

  useEffect(() => {
    Promise.all([loadContracts(), loadClients(), loadContractTemplates()])
      .catch(err => addToast(err?.toString?.() || 'Failed to load', 'error'))
      .finally(() => setLoading(false));
  }, [loadContracts, loadClients, loadContractTemplates]);

  useEffect(() => {
    getUnlockedAchievementKeys().then((keys) => {
      setShowTemplatesTab(new Set(keys).has('first_contract'));
    });
  }, []);

  const openNew = () => {
    setEditing(null);
    setForm({ client_id: '', title: '', body: '' });
    setShowModal(true);
  };

  const openNewFromTemplate = (template: ContractTemplate) => {
    setEditing(null);
    setForm({ client_id: '', title: '', body: template.body });
    setShowModal(true);
    setShowTemplatePicker(false);
    if (tab === 'templates') setTab('contracts');
  };

  const openEdit = (c: Contract) => {
    setEditing(c);
    setForm({ client_id: c.client_id, title: c.title, body: ensureHtml(c.body || '') });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.title.trim() || !form.client_id) return;
    setSaving(true);
    try {
      if (editing) {
        await updateContract({ ...editing, ...form, body: form.body || '' });
      } else {
        await addContract({ ...form, body: form.body || '', status: 'draft' });
      }
      setShowModal(false);
      checkAndNotify(useStore.getState(), addToast);
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to save', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handleSaveAsTemplate = async (c: Contract) => {
    try {
      await addContractTemplate({
        name: c.title || 'Untitled Template',
        category: 'Custom',
        body: c.body || '',
        variables: [],
      });
      addToast('Contract saved as template', 'success');
    } catch {
      addToast('Failed to save template', 'error');
    }
  };

  const handleActivate = async (c: Contract) => {
    try {
      await updateContract({ ...c, status: 'active' as const });
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to activate', 'error');
    }
  };

  const handleComplete = async (c: Contract) => {
    try {
      await updateContract({ ...c, status: 'completed' as const });
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to complete', 'error');
    }
  };

  const handleDelete = async () => {
    if (!confirmDelete) return;
    setDeleting(true);
    try {
      await removeContract(confirmDelete.id);
      setConfirmDelete(null);
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to delete', 'error');
    } finally {
      setDeleting(false);
    }
  };

  const handleDeleteTemplate = async (id: string) => {
    try {
      await removeContractTemplate(id);
      addToast('Template deleted', 'info');
    } catch {
      addToast('Failed to delete template', 'error');
    }
  };

  const getClientName = (clientId: string) => clients.find((c) => c.id === clientId)?.name || 'Unknown';

  const filtered = contracts.filter((c) => {
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    return c.title.toLowerCase().includes(q) || getClientName(c.client_id).toLowerCase().includes(q);
  });

  const allTemplates = [...PREBUILT_TEMPLATES.map((t) => ({ ...t, id: `prebuilt:${t.name}`, created_at: '' })), ...contractTemplates];

  if (loading) return (
    <div className="p-6">
      <div className="h-6 w-24 bg-[var(--bg-secondary)] rounded skeleton-pulse mb-1.5" />
      <div className="h-4 w-32 bg-[var(--bg-secondary)] rounded skeleton-pulse mb-6" />
      {[...Array(4)].map((_, i) => <div key={i} className="h-20 bg-[var(--bg-secondary)] rounded-[8px] skeleton-pulse mb-3" />)}
    </div>
  );

  const TabBar = () => (
    <div className="flex items-center gap-4 mb-6">
      <button
        onClick={() => setTab('contracts')}
        className={`text-sm font-medium pb-1.5 border-b-2 transition-colors ${
          tab === 'contracts'
            ? 'text-[var(--text-primary)] border-[var(--accent)]'
            : 'text-[var(--text-tertiary)] border-transparent hover:text-[var(--text-secondary)]'
        }`}
      >
        Contracts
      </button>
      {showTemplatesTab && (
        <button
          onClick={() => setTab('templates')}
          className={`text-sm font-medium pb-1.5 border-b-2 transition-colors flex items-center gap-1.5 ${
            tab === 'templates'
              ? 'text-[var(--text-primary)] border-[var(--accent)]'
              : 'text-[var(--text-tertiary)] border-transparent hover:text-[var(--text-secondary)]'
          }`}
        >
          <FileText size={14} />
          Templates
        </button>
      )}
    </div>
  );

  return (
    <div className="p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-lg font-semibold text-[var(--text-primary)]">Contracts</h2>
          <p className="text-sm text-[var(--text-secondary)] mt-0.5">
            {contracts.filter((c) => c.status === 'active').length} active, {contracts.length} total
          </p>
        </div>
        {tab === 'contracts' && (
          <div className="flex items-center gap-2">
            {showTemplatesTab && (
              <Button onClick={() => setShowTemplatePicker(true)} size="sm" variant="secondary" disabled={clients.length === 0}>
                <Copy size={14} />
                Start from template
              </Button>
            )}
            <Button onClick={openNew} size="sm" disabled={clients.length === 0}>
              <Plus size={14} />
              New Contract
            </Button>
          </div>
        )}
      </div>

      <TabBar />

      {tab === 'contracts' ? (
        <>
          {clients.length > 0 && contracts.length > 0 && (
            <div className="mb-4 relative">
              <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--text-tertiary)]" />
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search contracts..."
                className="w-full pl-9 pr-3 py-2 text-sm border border-[var(--border-color)] rounded-[8px] placeholder:text-[var(--text-tertiary)] focus:outline-none focus:border-[var(--accent)] bg-[var(--bg-card)]"
              />
            </div>
          )}

          {clients.length === 0 ? (
            <Card className="mb-4 border-[#FAEEDA] bg-[#FAEEDA]/50">
              <p className="text-sm text-[#854F0B]">
                Add at least one client before creating a contract.
              </p>
            </Card>
          ) : contracts.length === 0 ? (
            <Card className="text-center py-16 flex flex-col items-center">
              <PenLine size={40} className="text-[var(--text-tertiary)] mb-4" />
              <h3 className="text-[15px] font-medium text-[var(--text-secondary)] mb-1.5">No contracts yet</h3>
              <p className="text-[13px] text-[var(--text-tertiary)] max-w-xs mb-5">Convert a proposal to get started.</p>
            </Card>
          ) : filtered.length === 0 ? (
            <Card className="text-center py-16 flex flex-col items-center">
              <Search size={40} className="text-[var(--text-tertiary)] mb-4" />
              <h3 className="text-[15px] font-medium text-[var(--text-secondary)] mb-1.5">No contracts match</h3>
              <p className="text-[13px] text-[var(--text-tertiary)] max-w-xs">Try a different search term.</p>
            </Card>
          ) : (
            <div className="space-y-3">
              {filtered.map((c) => (
                <Card key={c.id}>
                  <div className="flex items-start justify-between">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="text-sm font-semibold text-[var(--text-primary)]">{c.title}</h3>
                        <Badge variant={statusBadge[c.status]}>{c.status}</Badge>
                      </div>
                      <p className="text-xs text-[var(--text-secondary)] mb-1">{getClientName(c.client_id)}</p>
                      {c.signed_at && (
                        <p className="text-xs text-[var(--text-tertiary)]">
                          Signed {relativeDate(c.signed_at)}
                        </p>
                      )}
                    </div>
                    <div className="flex items-center gap-1 flex-shrink-0 ml-3">
                      {c.status === 'draft' && (
                        <button
                          onClick={() => handleActivate(c)}
                          className="text-xs text-[var(--accent)] hover:underline px-1"
                        >
                          Activate
                        </button>
                      )}
                      {c.status === 'active' && (
                        <button
                          onClick={() => handleComplete(c)}
                          className="text-xs text-[var(--accent)] hover:underline px-1"
                        >
                          Complete
                        </button>
                      )}
                      <button
                        onClick={() => setExpanded(expanded === c.id ? null : c.id)}
                        aria-label="View contract body"
                        className={`p-1.5 rounded-[8px] transition-colors ${expanded === c.id ? 'text-[var(--accent)] bg-[var(--accent-bg)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-secondary)]'}`}
                      >
                        <Eye size={14} />
                      </button>
                      <button
                        onClick={() => openEdit(c)}
                        aria-label="Edit contract"
                        className="p-1.5 rounded-[8px] text-[var(--text-tertiary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-secondary)] transition-colors"
                      >
                        <Pencil size={14} />
                      </button>
                      {c.status !== 'active' && (
                        <button
                          onClick={() => handleSaveAsTemplate(c)}
                          aria-label="Save as template"
                          className="p-1.5 rounded-[8px] text-[var(--text-tertiary)] hover:text-[var(--accent)] hover:bg-[var(--accent-bg)] transition-colors"
                          title="Save as template"
                        >
                          <Copy size={14} />
                        </button>
                      )}
                      <button
                        onClick={() => setConfirmDelete({ id: c.id, title: c.title })}
                        aria-label="Delete contract"
                        className="p-1.5 rounded-[8px] text-[var(--text-tertiary)] hover:text-[#A32D2D] hover:bg-[#FCEBEB] transition-colors"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </div>
                  {expanded === c.id && c.body && (
                    <div className="mt-3 pt-3 border-t border-[var(--border-color)]">
                      <p className="text-xs text-[var(--text-primary)] whitespace-pre-wrap leading-relaxed">{htmlToPlainText(c.body)}</p>
                    </div>
                  )}
                </Card>
              ))}
            </div>
          )}
        </>
      ) : (
        /* ── Templates tab ── */
        <div className="space-y-3">
          {allTemplates.length === 0 ? (
            <Card className="text-center py-16 flex flex-col items-center">
              <FileText size={40} className="text-[var(--text-tertiary)] mb-4" />
              <h3 className="text-[15px] font-medium text-[var(--text-secondary)] mb-1.5">No templates yet</h3>
              <p className="text-[13px] text-[var(--text-tertiary)] max-w-xs">Save a contract as a template or use one of the pre-built options.</p>
            </Card>
          ) : (
            allTemplates.map((t) => {
              const isPrebuilt = t.id.startsWith('prebuilt:');
              return (
                <Card key={t.id}>
                  <div className="flex items-start justify-between">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="text-sm font-semibold text-[var(--text-primary)]">{t.name}</h3>
                        {t.category && (
                          <Badge variant={TEMPLATE_BADGE_COLORS[t.category] as 'info' || 'info'}>
                            {t.category}
                          </Badge>
                        )}
                        {isPrebuilt && <Badge variant="success">Pre-built</Badge>}
                      </div>
                      {t.variables && t.variables.length > 0 && (
                        <div className="flex flex-wrap gap-1 mt-1.5">
                          {t.variables.map((v) => (
                            <code key={v} className="text-[9px] px-1.5 py-0.5 bg-[var(--bg-secondary)] rounded text-[var(--text-tertiary)]">
                              {v}
                            </code>
                          ))}
                        </div>
                      )}
                      <div className="mt-2 text-xs text-[var(--text-secondary)] leading-relaxed line-clamp-3">
                        {htmlToPlainText(t.body || '').substring(0, 200)}...
                      </div>
                    </div>
                    <div className="flex items-center gap-1 flex-shrink-0 ml-3">
                      {clients.length > 0 ? (
                        <button
                          onClick={() => openNewFromTemplate(t)}
                          className="text-xs text-[var(--accent)] hover:underline px-1"
                        >
                          Use template
                        </button>
                      ) : (
                        <span className="text-[10px] text-[var(--text-tertiary)]">Add a client first</span>
                      )}
                      {!isPrebuilt && (
                        <button
                          onClick={() => handleDeleteTemplate(t.id)}
                          className="p-1.5 rounded-[8px] text-[var(--text-tertiary)] hover:text-[#A32D2D] hover:bg-[#FCEBEB] transition-colors"
                        >
                          <Trash2 size={14} />
                        </button>
                      )}
                    </div>
                  </div>
                </Card>
              );
            })
          )}
        </div>
      )}

      <Modal open={showModal} onClose={() => setShowModal(false)} title={editing ? 'Edit Contract' : 'New Contract'} size="md">
        <div className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Client *</label>
            <ClientSelect
              clients={clients}
              value={form.client_id}
              onChange={(clientId) => setForm({ ...form, client_id: clientId })}
              placeholder="Select a client..."
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Title *</label>
            <input
              type="text"
              value={form.title}
              onChange={(e) => setForm({ ...form, title: e.target.value })}
              placeholder="Contract title"
              className="w-full px-3 py-2 text-sm border border-[var(--border-color)] rounded-[8px] placeholder:text-[var(--text-tertiary)] focus:outline-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/20"
              autoFocus
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Contract Body</label>
            <RichEditor
              content={form.body}
              onChange={(html) => setForm({ ...form, body: html })}
              placeholder="Write the contract terms..."
              minHeight={240}
            />
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="secondary" onClick={() => setShowModal(false)} size="sm">Cancel</Button>
            <Button onClick={handleSave} loading={saving} disabled={!form.title.trim() || !form.client_id} size="sm">
              {editing ? 'Save Changes' : 'Create Contract'}
            </Button>
          </div>
        </div>
      </Modal>

      {/* Template picker modal */}
      {showTemplatesTab && (
        <Modal open={showTemplatePicker} onClose={() => setShowTemplatePicker(false)} title="Start from Template" size="md">
          <div className="space-y-2 max-h-[400px] overflow-y-auto">
            {allTemplates.length === 0 ? (
              <p className="text-sm text-[var(--text-tertiary)] py-8 text-center">No templates available.</p>
            ) : (
              allTemplates.map((t) => (
                <button
                  key={t.id}
                  onClick={() => openNewFromTemplate(t)}
                  className="w-full text-left p-3 rounded-[8px] border border-[var(--border-color)] hover:border-[var(--accent)] hover:bg-[var(--accent-bg)]/30 transition-colors"
                >
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-sm font-medium text-[var(--text-primary)]">{t.name}</span>
                    {t.category && <Badge variant={TEMPLATE_BADGE_COLORS[t.category] as 'info' || 'info'}>{t.category}</Badge>}
                  </div>
                  <p className="text-[11px] text-[var(--text-secondary)] line-clamp-2">
                    {htmlToPlainText(t.body || '').substring(0, 120)}
                  </p>
                </button>
              ))
            )}
          </div>
        </Modal>
      )}

      <ConfirmDialog
        open={!!confirmDelete}
        onClose={() => setConfirmDelete(null)}
        onConfirm={handleDelete}
        title="Delete Contract"
        message={`Are you sure you want to delete "${confirmDelete?.title}"? This cannot be undone.`}
        loading={deleting}
      />
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useStore } from '../store';
import Card from '../components/ui/Card';
import MetricCard from '../components/ui/MetricCard';
import Button from '../components/ui/Button';
import { relativeDate, formatCurrency } from '../utils/format';
import { useToasts } from '../store/toastStore';
import { Play, Receipt, FileText, Users, FolderKanban, Clock, Plus, ArrowRight, CheckCircle2, Circle, Bell, Send, Check, X } from 'lucide-react';
import { generateFollowUpDraft } from '../utils/followUpTemplates';
import { getArchetype } from '../archetypes';
import type { ArchetypeConfig } from '../archetypes';
import { getDb } from '../db';
import * as queries from '../archetypes/queries';

export default function Dashboard() {
  const { invoices, loadInvoices, proposals, loadProposals, projects, loadProjects, clients, loadClients, timeEntries, loadTimeEntries, profile, loadProfile, expenses, loadExpenses, pendingFollowUps, loadPendingFollowUps, updateFollowUpStatus, followUpSettings } = useStore();
  const addToast = useToasts((s) => s.add);
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [archetype, setArchetype] = useState<ArchetypeConfig | null>(null);
  const [metricValues, setMetricValues] = useState<Record<string, string | number>>({});

  useEffect(() => {
    Promise.all([loadInvoices(), loadProposals(), loadProjects(), loadClients(), loadTimeEntries(), loadExpenses(), loadProfile(), loadPendingFollowUps()])
      .catch(err => addToast(err?.toString?.() || 'Failed to load', 'error'))
      .finally(() => setLoading(false));
  }, [loadInvoices, loadProposals, loadProjects, loadClients, loadTimeEntries, loadExpenses, loadProfile, loadPendingFollowUps]);

  useEffect(() => {
    if (!profile) return;
    let config: ArchetypeConfig;
    if (profile.profession === 'custom' && (profile as any).custom_archetype_config) {
      try {
        config = JSON.parse((profile as any).custom_archetype_config);
      } catch {
        config = getArchetype(profile.profession || 'default');
      }
    } else {
      config = getArchetype(profile.profession || 'default');
    }
    setArchetype(config);
  }, [profile]);

  useEffect(() => {
    if (!archetype) return;
    const loadMetrics = async () => {
      const db = await getDb();
      const values: Record<string, string | number> = {};
      for (const card of archetype.dashboard.metricCards) {
        try {
          if (card.query) {
            values[card.id] = await card.query(db, profile?.id || 1);
          } else {
            const queryFn = (queries as any)[card.id];
            if (queryFn) {
              values[card.id] = await queryFn(db, profile?.id || 1);
            } else {
              values[card.id] = '—';
            }
          }
        } catch {
          values[card.id] = '—';
        }
      }
      setMetricValues(values);
    };
    loadMetrics();
  }, [archetype, profile]);

  if (!archetype) {
    const config = getArchetype('default');
    setArchetype(config);
  }

  const unpaidInvoices = invoices.filter(i => i.status === 'sent' || i.status === 'overdue');
  const activeProjects = projects.filter(p => p.status === 'active');
  const draftProposals = proposals.filter(p => p.status === 'draft');
  const totalOutstanding = unpaidInvoices.reduce((s, i) => s + i.total, 0);
  const totalPaid = invoices.filter(i => i.status === 'paid').reduce((s, i) => s + i.total, 0);
  const todaysMinutes = timeEntries.filter(t => t.start_time.startsWith(new Date().toISOString().split('T')[0])).reduce((s, t) => s + (t.duration_minutes || 0), 0);

  const recentInvoices = [...invoices].sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()).slice(0, 5);
  const recentTime = [...timeEntries].filter(t => t.duration_minutes).sort((a, b) => new Date(b.start_time).getTime() - new Date(a.start_time).getTime()).slice(0, 5);

  const hasData = clients.length > 0 || invoices.length > 0 || projects.length > 0;
  const effectiveArchetype = archetype || getArchetype('default');

  if (loading) {
    return (
      <div className="p-6 space-y-6">
        <div className="h-6 w-32 bg-[var(--bg-secondary)] rounded skeleton-pulse mb-1" />
        <div className="h-4 w-48 bg-[var(--bg-secondary)] rounded skeleton-pulse mb-4" />
        <div className="grid grid-cols-4 gap-3">
          {[...Array(4)].map((_, i) => <div key={i} className="h-24 rounded-[12px] bg-[var(--bg-secondary)] skeleton-pulse" />)}
        </div>
        <div className="grid grid-cols-2 gap-6">
          <div className="h-48 rounded-[12px] bg-[var(--bg-secondary)] skeleton-pulse" />
          <div className="h-48 rounded-[12px] bg-[var(--bg-secondary)] skeleton-pulse" />
        </div>
      </div>
    );
  }

  const steps = [
    { done: clients.length > 0, label: 'Add your first client', to: '/clients', icon: Users },
    { done: projects.length > 0, label: 'Create a project', to: '/projects', icon: FolderKanban },
    { done: timeEntries.length > 0, label: 'Log some time', to: '/time', icon: Clock },
    { done: proposals.length > 0, label: 'Send a proposal', to: '/proposals/new', icon: FileText },
    { done: invoices.length > 0, label: 'Send an invoice', to: '/invoices', icon: Receipt },
  ];
  const allDone = steps.every(s => s.done);
  const nextStep = steps.find(s => !s.done);

  return (
    <div className="p-6">
      <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-1">
        {effectiveArchetype.dashboard.greeting}
      </h2>
      <p className="text-sm text-[var(--text-secondary)] mb-6">
        {profile?.name?.trim()
          ? `${effectiveArchetype.dashboard.subgreeting.replace('Your', `${profile.name.split(' ')[0]}'s`)}`
          : effectiveArchetype.dashboard.subgreeting}
      </p>

      {!hasData && (
        <Card className="mb-6 border-[var(--accent)]/20 bg-[var(--accent-bg)]">
          <div className="flex items-start gap-4">
            <div className="w-10 h-10 rounded-full bg-[var(--accent)]/10 flex items-center justify-center flex-shrink-0">
              <Play size={20} className="text-[var(--accent)]" />
            </div>
            <div className="flex-1">
              <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-1">Let's get you set up</h3>
              <p className="text-xs text-[var(--text-secondary)] mb-3">Everything in Lance starts with a client. Follow these steps to get going.</p>
              <div className="space-y-2 mb-4">
                {steps.map((s, i) => (
                  <button
                    key={i}
                    onClick={() => navigate(s.to)}
                    className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-[8px] text-left text-xs transition-colors ${
                      s.done
                        ? 'bg-[var(--bg-secondary)] text-[var(--text-tertiary)] line-through cursor-default'
                        : 'bg-[var(--bg-card)] text-[var(--text-primary)] hover:bg-[var(--bg-secondary)] border border-[var(--border-color)]'
                    }`}
                    disabled={s.done}
                  >
                    {s.done ? <CheckCircle2 size={14} className="text-[var(--accent)]" /> : <Circle size={14} className="text-[var(--text-tertiary)]" />}
                    <s.icon size={14} className={s.done ? 'text-[var(--text-tertiary)]' : 'text-[var(--accent)]'} />
                    {s.label}
                    {!s.done && <ArrowRight size={12} className="ml-auto text-[var(--text-tertiary)]" />}
                  </button>
                ))}
              </div>
              {allDone && (
                <p className="text-xs text-[var(--accent)] font-medium">You're all set. Explore the sections in the sidebar.</p>
              )}
            </div>
          </div>
        </Card>
      )}

      <div className="grid grid-cols-4 gap-3 mb-6">
        {effectiveArchetype.dashboard.metricCards.map((card) => (
          <MetricCard
            key={card.id}
            label={card.label}
            value={metricValues[card.id] ?? '...'}
            color={card.color || 'gray'}
            tooltip={card.tooltip}
          />
        ))}
      </div>

      {/* Needs Attention — Follow-ups */}
      {pendingFollowUps.length > 0 && (
        <Card className="mb-6 border-[var(--accent)]/20">
          <div className="flex items-center gap-2 mb-3">
            <Bell size={14} className="text-[var(--accent)]" />
            <h3 className="text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wide">Needs Attention</h3>
            <span className="text-[10px] font-medium px-1.5 py-0.5 rounded-full bg-[var(--accent-bg)] text-[var(--accent)]">{pendingFollowUps.length}</span>
          </div>
          <div className="space-y-2">
            {pendingFollowUps.slice(0, 3).map((fu) => {
              const isProposal = fu.entity_type === 'proposal';
              const entity = isProposal
                ? proposals.find((p) => p.id === fu.entity_id)
                : invoices.find((i) => i.id === fu.entity_id);
              if (!entity) return null;
              const client = clients.find((c) => c.id === (isProposal ? (entity as typeof proposals[0]).client_id : (entity as typeof invoices[0]).client_id));
              const daysElapsed = Math.floor((Date.now() - (isProposal ? new Date((entity as typeof proposals[0]).sent_at || (entity as typeof proposals[0]).created_at).getTime() : new Date((entity as typeof invoices[0]).due_date || '').getTime())) / 86400000);
              const templateKey = isProposal
                ? (daysElapsed >= 10 ? 'proposal_day14' : daysElapsed >= 4 ? 'proposal_day7' : 'proposal_day3')
                : (daysElapsed >= 10 ? 'invoice_day14' : daysElapsed >= 4 ? 'invoice_day7' : 'invoice_day1');
              const draft = generateFollowUpDraft(templateKey, {
                clientName: client?.name || 'Unknown',
                proposalTitle: isProposal ? (entity as typeof proposals[0]).title : undefined,
                invoiceNumber: isProposal ? undefined : (entity as typeof invoices[0]).invoice_number,
                amount: isProposal ? undefined : formatCurrency((entity as typeof invoices[0]).total),
                dueDate: isProposal ? undefined : (entity as typeof invoices[0]).due_date,
                daysElapsed,
                projectName: '',
                freelancerName: profile?.name || 'Freelancer',
              }, followUpSettings.templates);
              return (
                <div key={fu.id} className="flex items-start justify-between px-3 py-2 rounded-[8px] bg-[var(--bg-secondary)]/50">
                  <div className="min-w-0 flex-1">
                    <p className="text-xs font-medium text-[var(--text-primary)]">
                      {isProposal ? 'Proposal' : 'Invoice'}: {isProposal ? (entity as typeof proposals[0]).title : (entity as typeof invoices[0]).invoice_number}
                    </p>
                    <p className="text-[10px] text-[var(--text-secondary)]">{client?.name || 'Unknown'} &middot; {daysElapsed}d</p>
                    <p className="text-[10px] text-[var(--text-tertiary)] mt-1 line-clamp-2">{draft.split('\n')[0]}</p>
                  </div>
                  <div className="flex items-center gap-1 flex-shrink-0 ml-3">
                    <button onClick={async () => { await updateFollowUpStatus(fu.id, 'dismissed', 'dismissed'); }} className="p-1 rounded-[6px] text-[var(--text-tertiary)] hover:text-[var(--text-primary)]" title="Dismiss"><X size={12} /></button>
                    <button onClick={async () => {
                      await navigator.clipboard.writeText(draft);
                      await updateFollowUpStatus(fu.id, 'sent', 'sent');
                      addToast('Copied to clipboard', 'success');
                    }} className="p-1 rounded-[6px] text-[var(--accent)] hover:bg-[var(--accent-bg)]" title="Copy & dismiss"><Send size={12} /></button>
                  </div>
                </div>
              );
            })}
          </div>
        </Card>
      )}

      {/* Quick Actions */}
      {hasData && effectiveArchetype.dashboard.quickActions.length > 0 && (
        <div className="flex gap-2 mb-6">
          {effectiveArchetype.dashboard.quickActions.map((action) => (
            <Button
              key={action.label}
              variant="secondary"
              size="sm"
              onClick={() => {
                if (action.action.startsWith('/')) {
                  navigate(action.action);
                } else {
                  document.dispatchEvent(new CustomEvent(`lance:${action.action}`));
                }
              }}
            >
              {action.label}
            </Button>
          ))}
        </div>
      )}

      <div className="grid grid-cols-2 gap-6">
        <Card>
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-semibold text-[var(--text-primary)]">Recent Invoices</h3>
            <button onClick={() => navigate('/invoices')} className="text-xs text-[var(--accent)] hover:underline">View all</button>
          </div>
          {recentInvoices.length === 0 ? (
            <div className="text-center py-8">
              <Receipt size={32} className="text-[var(--text-tertiary)] mx-auto mb-2" />
              <p className="text-xs text-[var(--text-tertiary)]">No invoices yet.</p>
              <Button onClick={() => navigate('/invoices')} size="sm" variant="secondary" className="mt-3">
                <Plus size={12} /> New Invoice
              </Button>
            </div>
          ) : (
            <div className="space-y-2">
              {recentInvoices.map(inv => (
                <div key={inv.id} className="flex items-center justify-between px-3 py-2 rounded-[8px] hover:bg-[var(--bg-secondary)] transition-colors">
                  <div>
                    <p className="text-xs font-medium text-[var(--text-primary)]">{inv.invoice_number}</p>
                    <p className="text-[10px] text-[var(--text-tertiary)]">{relativeDate(inv.created_at)}</p>
                  </div>
                  <div className="text-right">
                    <p className={`text-xs font-medium ${inv.status === 'overdue' ? 'text-[#A32D2D]' : inv.status === 'paid' ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'}`}>
                      {formatCurrency(inv.total, profile?.currency)}
                    </p>
                    <p className="text-[10px] text-[var(--text-tertiary)] capitalize">{inv.status}</p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>

        <Card>
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-semibold text-[var(--text-primary)]">Recent Time</h3>
            <button onClick={() => navigate('/time')} className="text-xs text-[var(--accent)] hover:underline">View all</button>
          </div>
          {recentTime.length === 0 ? (
            <div className="text-center py-8">
              <Clock size={32} className="text-[var(--text-tertiary)] mx-auto mb-2" />
              <p className="text-xs text-[var(--text-tertiary)]">No time tracked yet.</p>
              <Button onClick={() => navigate('/time')} size="sm" variant="secondary" className="mt-3">
                <Play size={12} /> Start Timer
              </Button>
            </div>
          ) : (
            <div className="space-y-2">
              {recentTime.map(entry => {
                const project = projects.find(p => p.id === entry.project_id);
                const mins = entry.duration_minutes || 0;
                return (
                  <div key={entry.id} className="flex items-center justify-between px-3 py-2 rounded-[8px] hover:bg-[var(--bg-secondary)] transition-colors">
                    <div>
                      <p className="text-xs font-medium text-[var(--text-primary)] truncate max-w-[180px]">
                        {entry.description || project?.title || 'Untitled'}
                      </p>
                      <p className="text-[10px] text-[var(--text-tertiary)]">{relativeDate(entry.start_time)}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-xs font-medium text-[var(--text-primary)]">{Math.floor(mins / 60)}h {mins % 60}m</p>
                      <p className="text-[10px] text-[var(--text-tertiary)]">{entry.billable ? 'billable' : 'non-billable'}</p>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </Card>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useStore } from '../store';
import type { Expense } from '../types';
import Button from '../components/ui/Button';
import Card from '../components/ui/Card';
import MetricCard from '../components/ui/MetricCard';
import Modal from '../components/ui/Modal';
import { formatCurrency, formatDate, formatMonth } from '../utils/format';
import ConfirmDialog from '../components/ui/ConfirmDialog';
import { useToasts } from '../store/toastStore';
import { checkAndNotify } from '../achievements/notify';
import { getUnlockedAchievementKeys } from '../achievements/checker';
import {
  getNextMonths,
  computeRevenueForecast,
  computeExpenseForecast,
  computeCashFlow,
  computeAvgClientRevenue,
  computeForecastMetrics,
  applyScenario,
  type ScenarioParams,
} from '../lib/forecast';
import { Plus, Pencil, Trash2, BarChart3, TrendingUp } from 'lucide-react';

const categories = ['Software', 'Equipment', 'Office', 'Travel', 'Marketing', 'Taxes', 'Other'];

export default function Finance() {
  const { expenses, loadExpenses, addExpense, updateExpense, removeExpense, invoices, loadInvoices, profile, recurringInvoices, loadRecurringInvoices, projects, loadProjects, milestones, loadMilestones } = useStore();
  const addToast = useToasts((s) => s.add);
  const currency = profile?.currency;
  const fmt = (amount: number) => formatCurrency(amount, currency);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState<Expense | null>(null);
  const [saving, setSaving] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState<{ id: string; description: string } | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [form, setForm] = useState({ category: 'Other', description: '', amount: '', date: new Date().toISOString().split('T')[0], recurring: false, frequency: 'monthly' });
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<'overview' | 'forecast'>('overview');
  const [showForecast, setShowForecast] = useState(false);
  const [currentBalance, setCurrentBalance] = useState('');
  const [scenario, setScenario] = useState<ScenarioParams>({ newClientsPerMonth: 0, rateIncrease: 0, expenseGrowth: 0, mode: 'base' });

  useEffect(() => {
    const loadAll = async () => {
      await Promise.all([loadExpenses(), loadInvoices(), loadRecurringInvoices(), loadProjects()]);
      const state = useStore.getState();
      const active = state.projects.filter((p) => p.status === 'active');
      await Promise.all(active.map((p) => loadMilestones(p.id)));
    };
    loadAll()
      .catch(err => addToast(err?.toString?.() || 'Failed to load', 'error'))
      .finally(() => setLoading(false));
  }, [loadExpenses, loadInvoices, loadRecurringInvoices, loadProjects, loadMilestones]);

  useEffect(() => {
    getUnlockedAchievementKeys().then((keys) => {
      setShowForecast(new Set(keys).has('first_recurring'));
    });
  }, []);

  const openNew = () => {
    setEditing(null);
    setForm({ category: 'Other', description: '', amount: '', date: new Date().toISOString().split('T')[0], recurring: false, frequency: 'monthly' });
    setShowModal(true);
  };

  const openEdit = (exp: Expense) => {
    setEditing(exp);
    setForm({ category: exp.category, description: exp.description, amount: exp.amount.toString(), date: exp.date, recurring: exp.recurring || false, frequency: exp.frequency || 'monthly' });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.description.trim() || !form.amount) return;
    setSaving(true);
    try {
      const data = {
        category: form.category,
        description: form.description,
        amount: parseFloat(form.amount),
        date: form.date,
        recurring: form.recurring,
        frequency: form.recurring ? form.frequency : undefined,
      };
      if (editing) {
        await updateExpense({ ...editing, ...data });
      } else {
        await addExpense(data);
      }
      setShowModal(false);
      checkAndNotify(useStore.getState(), addToast);
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to save expense', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!confirmDelete) return;
    setDeleting(true);
    try {
      await removeExpense(confirmDelete.id);
      setConfirmDelete(null);
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to delete expense', 'error');
    } finally {
      setDeleting(false);
    }
  };

  const totalExpenses = expenses.reduce((sum, e) => sum + e.amount, 0);
  const totalPaid = invoices.filter((i) => i.status === 'paid').reduce((sum, i) => sum + i.total, 0);
  const totalOutstanding = invoices.filter((i) => i.status === 'sent' || i.status === 'overdue').reduce((sum, i) => sum + i.total, 0);
  const profit = totalPaid - totalExpenses;

  const expensesByCategory = categories.map((cat) => {
    const total = expenses.filter((e) => e.category === cat).reduce((s, e) => s + e.amount, 0);
    return { category: cat, total };
  }).filter((c) => c.total > 0);

  const monthlyExpenses: Record<string, number> = {};
  expenses.forEach((e) => {
    const month = e.date.substring(0, 7);
    monthlyExpenses[month] = (monthlyExpenses[month] || 0) + e.amount;
  });

  const monthlyPaid: Record<string, number> = {};
  invoices.filter((i) => i.status === 'paid' && i.paid_at).forEach((i) => {
    const month = i.paid_at!.substring(0, 7);
    monthlyPaid[month] = (monthlyPaid[month] || 0) + i.total;
  });

  const allMonths = Array.from(new Set([...Object.keys(monthlyExpenses), ...Object.keys(monthlyPaid)])).sort().reverse().slice(0, 12);

  // ── Forecast computations ──
  const forecastMonths = getNextMonths(6);
  const avgClientRevenue = computeAvgClientRevenue(invoices);

  const baseRevenue = computeRevenueForecast(
    recurringInvoices, invoices, projects, milestones, monthlyPaid, forecastMonths,
  );
  const baseExpenses = computeExpenseForecast(expenses, monthlyExpenses, forecastMonths);

  const scenarioResult = applyScenario(baseRevenue, baseExpenses, avgClientRevenue, scenario);
  const revenueForecast = scenarioResult.revenue;
  const expenseForecast = scenarioResult.expenses;
  const cashFlow = computeCashFlow(
    revenueForecast,
    expenseForecast,
    currentBalance ? parseFloat(currentBalance) : undefined,
  );

  const forecastMetrics = computeForecastMetrics(
    revenueForecast,
    expenseForecast,
    forecastMonths,
    currentBalance ? parseFloat(currentBalance) : undefined,
  );

  const maxRevenue = Math.max(1, ...revenueForecast.map((d) => Math.max(d.confirmed, d.probable, d.projected, d.baseline)));
  const maxExpense = Math.max(1, ...expenseForecast.map((d) => Math.max(d.known, d.projected, d.baseline)));

  if (loading) return (
    <div className="p-6">
      <div className="grid grid-cols-4 gap-3 mb-6">
        {[...Array(4)].map((_, i) => <div key={i} className="h-24 rounded-[12px] bg-[var(--bg-secondary)] skeleton-pulse" />)}
      </div>
      <div className="grid grid-cols-2 gap-6 mb-6">
        <div className="h-48 rounded-[12px] bg-[var(--bg-secondary)] skeleton-pulse" />
        <div className="h-48 rounded-[12px] bg-[var(--bg-secondary)] skeleton-pulse" />
      </div>
    </div>
  );

  const TabBar = () => (
    <div className="flex items-center gap-4 mb-6">
      <button
        onClick={() => setTab('overview')}
        className={`text-sm font-medium pb-1.5 border-b-2 transition-colors ${
          tab === 'overview'
            ? 'text-[var(--text-primary)] border-[var(--accent)]'
            : 'text-[var(--text-tertiary)] border-transparent hover:text-[var(--text-secondary)]'
        }`}
      >
        Overview
      </button>
      {showForecast && (
        <button
          onClick={() => setTab('forecast')}
          className={`text-sm font-medium pb-1.5 border-b-2 transition-colors flex items-center gap-1.5 ${
            tab === 'forecast'
              ? 'text-[var(--text-primary)] border-[var(--accent)]'
              : 'text-[var(--text-tertiary)] border-transparent hover:text-[var(--text-secondary)]'
          }`}
        >
          <TrendingUp size={14} />
          Forecast
        </button>
      )}
    </div>
  );

  return (
    <div className="p-6">
      <TabBar />

      {tab === 'overview' ? (
        <>
          <div className="grid grid-cols-4 gap-3 mb-6">
            <MetricCard label="Revenue (Paid)" value={fmt(totalPaid)} color="green" />
            <MetricCard label="Expenses" value={fmt(totalExpenses)} color="red" />
            <MetricCard
              label="Profit"
              value={fmt(profit)}
              trend={profit >= 0 ? 'up' : 'down'}
              subtext={profit >= 0 ? 'positive' : 'negative'}
              color={profit >= 0 ? 'green' : 'red'}
            />
            <MetricCard label="Outstanding" value={fmt(totalOutstanding)} subtext="unpaid invoices" color="amber" />
          </div>

          <div className="grid grid-cols-2 gap-6 mb-6">
            <Card>
              <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-3">Monthly Overview</h3>
              {allMonths.length === 0 ? (
                <p className="text-xs text-[var(--text-tertiary)]">No data yet.</p>
              ) : (
                <div className="space-y-2">
                  {allMonths.map((month) => {
                    const expense = monthlyExpenses[month] || 0;
                    const income = monthlyPaid[month] || 0;
                    const net = income - expense;
