                <div className="flex items-center gap-1.5"><div className="w-3 h-3 rounded-sm bg-[var(--accent)]/20" /><span className="text-[10px] text-[var(--text-secondary)]">Projected</span></div>
              </div>
            </Card>

            {/* PANEL 2 — Expense Forecast */}
            <Card>
