                  <option value="weekly">Weekly</option>
                  <option value="biweekly">Biweekly</option>
                  <option value="monthly">Monthly</option>
                  <option value="quarterly">Quarterly</option>
                </select>
              </div>
            )}
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="secondary" onClick={() => setShowModal(false)} size="sm">Cancel</Button>
            <Button onClick={handleSave} loading={saving} disabled={!form.description.trim() || !form.amount} size="sm">
              {editing ? 'Save Changes' : 'Add Expense'}
            </Button>
          </div>
        </div>
      </Modal>

      <ConfirmDialog
        open={!!confirmDelete}
        onClose={() => setConfirmDelete(null)}
        onConfirm={handleDelete}
        title="Delete Expense"
        message={`Are you sure you want to delete "${confirmDelete?.description}"? This cannot be undone.`}
        loading={deleting}
      />
    </div>
  );
}

import { useEffect, useState, useMemo } from 'react';
import { useStore } from '../store';
import Card from '../components/ui/Card';
import MetricCard from '../components/ui/MetricCard';
import ProgressBar from '../components/ui/ProgressBar';
import Sparkline from '../components/ui/Sparkline';
import { formatCurrency } from '../utils/format';
import { useToasts } from '../store/toastStore';
import { Lightbulb, BarChart3, TrendingUp, TrendingDown, Minus, Star } from 'lucide-react';
import { getArchetype } from '../archetypes';
import type { ArchetypeConfig } from '../archetypes';

export default function Insights() {
  const { projects, loadProjects, invoices, loadInvoices, timeEntries, loadTimeEntries, clients, loadClients, proposals, loadProposals, expenses, loadExpenses, profile, loadProfile, headlineMetrics, loadHeadlineMetrics } = useStore();
  const addToast = useToasts((s) => s.add);
  const [loaded, setLoaded] = useState(false);

  const archetype = useMemo(() => getArchetype(profile?.profession || 'default'), [profile?.profession]);

  useEffect(() => {
    Promise.all([
      loadProjects(),
      loadInvoices(),
      loadTimeEntries(),
      loadClients(),
      loadProposals(),
      loadExpenses(),
      loadProfile(),
      loadHeadlineMetrics(),
    ])
      .catch(err => addToast(err?.toString?.() || 'Failed to load', 'error'))
      .finally(() => setLoaded(true));
  }, [loadProjects, loadInvoices, loadTimeEntries, loadClients, loadProposals, loadExpenses, loadProfile]);

  const activeProjects = projects.filter((p) => p.status === 'active').length;
  const completedProjects = projects.filter((p) => p.status === 'completed').length;
  const totalProjects = projects.length;

  const totalInvoiced = invoices.reduce((sum, i) => sum + i.total, 0);
  const totalPaid = invoices.filter((i) => i.status === 'paid').reduce((sum, i) => sum + i.total, 0);
  const totalOutstanding = invoices.filter((i) => i.status === 'sent' || i.status === 'overdue').reduce((sum, i) => sum + i.total, 0);
  const overdueInvoices = invoices.filter((i) => i.status === 'overdue').length;

  const totalHoursTracked = timeEntries.reduce((sum, t) => sum + (t.duration_minutes || 0), 0);
  const hoursThisWeek = timeEntries.filter((t) => {
    const d = new Date(t.start_time);
    const now = new Date();
    const weekAgo = new Date(now.getTime() - 7 * 86400000);
    return d >= weekAgo;
  }).reduce((sum, t) => sum + (t.duration_minutes || 0), 0);

  const proposalsAccepted = proposals.filter((p) => p.status === 'accepted').length;
  const totalProposals = proposals.length;
  const winRate = totalProposals > 0 ? Math.round((proposalsAccepted / totalProposals) * 100) : 0;

  const totalExpenses = expenses.reduce((sum, e) => sum + e.amount, 0);
  const profitMargin = totalPaid > 0 ? Math.round(((totalPaid - totalExpenses) / totalPaid) * 100) : 0;

  // Client revenue ranking
  const clientRevenue: Record<string, { name: string; total: number; count: number }> = {};
  invoices.filter((i) => i.status === 'paid').forEach((inv) => {
    const client = clients.find((c) => c.id === inv.client_id);
    const name = client?.name || inv.client_id;
    if (!clientRevenue[inv.client_id]) {
      clientRevenue[inv.client_id] = { name, total: 0, count: 0 };
    }
    clientRevenue[inv.client_id].total += inv.total;
    clientRevenue[inv.client_id].count += 1;
  });
  const topClients = Object.values(clientRevenue).sort((a, b) => b.total - a.total).slice(0, 5);

  // Time by project
  const projectTime: Record<string, { name: string; minutes: number }> = {};
  timeEntries.forEach((t) => {
    const project = projects.find((p) => p.id === t.project_id);
    const name = project?.title || t.project_id;
    if (!projectTime[t.project_id]) {
      projectTime[t.project_id] = { name, minutes: 0 };
    }
    projectTime[t.project_id].minutes += t.duration_minutes || 0;
  });
  const topProjectsByTime = Object.values(projectTime).sort((a, b) => b.minutes - a.minutes).slice(0, 5);

  const hiddenPanels = archetype.insights.hidePanels || [];

  if (!loaded) return (
    <div className="p-6">
      <div className="h-6 w-48 bg-[var(--bg-secondary)] rounded skeleton-pulse mb-6" />
      <div className="grid grid-cols-4 gap-3 mb-6">
        {[...Array(4)].map((_, i) => <div key={i} className="h-24 rounded-[12px] bg-[var(--bg-secondary)] skeleton-pulse" />)}
      </div>
      <div className="grid grid-cols-2 gap-6">
        <div className="h-48 rounded-[12px] bg-[var(--bg-secondary)] skeleton-pulse" />
        <div className="h-48 rounded-[12px] bg-[var(--bg-secondary)] skeleton-pulse" />
      </div>
    </div>
  );

  const hasMinimalData = invoices.length > 0 || projects.length > 0;

  if (!hasMinimalData) {
    return (
      <div className="p-6">
        <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-6">{archetype.insights.headline}</h2>
        <Card className="text-center py-16 flex flex-col items-center">
          <Lightbulb size={40} className="text-[var(--text-tertiary)] mb-4" />
          <h3 className="text-[15px] font-medium text-[var(--text-secondary)] mb-1.5">Not enough data yet</h3>
          <p className="text-[13px] text-[var(--text-tertiary)] max-w-xs mb-5">Insights appear after you create an invoice or project. Start tracking to see your data.</p>
        </Card>
      </div>
    );
  }

  return (
    <div className="p-6">
      <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-6">{archetype.insights.headline}</h2>

      <div className="grid grid-cols-4 gap-3 mb-6">
        <MetricCard label="Active Projects" value={activeProjects} subtext={`${completedProjects} completed`} color="gray" />
        <MetricCard label="Total Revenue" value={formatCurrency(totalPaid, profile?.currency)} subtext={`${invoices.filter((i) => i.status === 'paid').length} paid invoices`} trend="up" color="green" />
        <MetricCard label="Outstanding" value={formatCurrency(totalOutstanding, profile?.currency)} subtext={overdueInvoices > 0 ? `${overdueInvoices} overdue` : 'all current'} trend={overdueInvoices > 0 ? 'down' : 'neutral'} color={overdueInvoices > 0 ? 'red' : 'amber'} />
        <MetricCard label="Win Rate" value={`${winRate}%`} subtext={`${proposalsAccepted}/${totalProposals} proposals`} trend={winRate >= 50 ? 'up' : 'down'} color={winRate >= 50 ? 'green' : 'gray'} />
      </div>

      <div className="grid grid-cols-2 gap-6 mb-6">
        {/* Project Health */}
        {!hiddenPanels.includes('project-health') && (
          <Card>
            <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-4">Project Health</h3>
            {totalProjects === 0 ? (
              <p className="text-xs text-[var(--text-tertiary)]">No projects yet.</p>
            ) : (
              <div className="space-y-4">
                <div className="flex justify-between text-xs">
                  <span className="text-[var(--text-secondary)]">Active</span>
                  <span className="font-medium text-[var(--text-primary)]">{activeProjects}</span>
                </div>
                <ProgressBar value={activeProjects} max={totalProjects || 1} label="Active" className="insight-bar-animate insight-bar-0" />
                <div className="flex justify-between text-xs">
                  <span className="text-[var(--text-secondary)]">Completed</span>
                  <span className="font-medium text-[var(--text-primary)]">{completedProjects}</span>
                </div>
                <ProgressBar value={completedProjects} max={totalProjects || 1} label="Completed" className="insight-bar-animate insight-bar-1" />
                <div className="flex justify-between text-xs mt-4 pt-3 border-t border-[var(--border-color)]">
                  <span className="text-[var(--text-secondary)]">Total Tracked</span>
                  <span className="font-medium text-[var(--text-primary)]">{Math.round(totalHoursTracked / 60)} hours</span>
                </div>
                <div className="flex justify-between text-xs">
                  <span className="text-[var(--text-secondary)]">This Week</span>
                  <span className="font-medium text-[var(--text-primary)]">{Math.round(hoursThisWeek / 60 * 10) / 10} hours</span>
                </div>
              </div>
            )}
          </Card>
        )}

        {/* Financial Health */}
        {!hiddenPanels.includes('financial-health') && (
          <Card>
            <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-4">Financial Health</h3>
            <div className="space-y-4">
              <div className="flex justify-between text-xs">
                <span className="text-[var(--text-secondary)]">Revenue</span>
                <span className="font-medium text-[var(--accent)]">{formatCurrency(totalPaid, profile?.currency)}</span>
              </div>
              <div className="flex justify-between text-xs">
                <span className="text-[var(--text-secondary)]">Expenses</span>
                <span className="font-medium text-[#A32D2D]">{formatCurrency(totalExpenses, profile?.currency)}</span>
              </div>
              <div className="flex justify-between text-xs pt-3 border-t border-[var(--border-color)]">
                <span className="text-[var(--text-secondary)]">Profit Margin</span>
