  active: 'success',
  completed: 'info',
  paused: 'warning',
  cancelled: 'danger',
};

type SortKey = 'title' | 'client' | 'status' | 'budget' | 'date';

export default function Projects() {
  const { projects, loadProjects, addProject, updateProject, removeProject, clients, loadClients, milestones, loadMilestones, addMilestone, updateMilestone, removeMilestone, invoices, loadInvoices, addInvoice, profile, loadProfile } = useStore();
  const addToast = useToasts((s) => s.add);
  const [showProjectModal, setShowProjectModal] = useState(false);
  const [showMilestoneModal, setShowMilestoneModal] = useState(false);
  const [selectedProject, setSelectedProject] = useState<string | null>(null);
  const [editingProject, setEditingProject] = useState<Project | null>(null);
  const [saving, setSaving] = useState(false);
  const [pform, setPForm] = useState({ client_id: '', title: '', status: 'active', start_date: '', end_date: '', budget: '', notes: '' });
  const [mform, setMForm] = useState({ title: '', due_date: '', invoice_on_completion: false });
  const [invoicePrompt, setInvoicePrompt] = useState<{ milestone: Milestone; project: Project } | null>(null);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [sortKey, setSortKey] = useState<SortKey>('date');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('desc');
  const [confirmDelete, setConfirmDelete] = useState<{ id: string; title: string } | null>(null);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    Promise.all([loadProjects(), loadClients(), loadProfile()])
      .catch(err => addToast(err?.toString?.() || 'Failed to load data', 'error'))
      .finally(() => setLoading(false));
  }, []);

  const openNewProject = () => {
    setEditingProject(null);
    setPForm({ client_id: '', title: '', status: 'active', start_date: '', end_date: '', budget: '', notes: '' });
    setShowProjectModal(true);
  };

  const openEditProject = (project: Project) => {
    setEditingProject(project);
    setPForm({
      client_id: project.client_id,
      title: project.title,
      status: project.status,
      start_date: project.start_date || '',
      end_date: project.end_date || '',
      budget: project.budget?.toString() || '',
      notes: project.notes || '',
    });
    setShowProjectModal(true);
  };

  const handleSaveProject = async () => {
    if (!pform.title.trim() || !pform.client_id) return;
    setSaving(true);
    try {
      const data = {
        client_id: pform.client_id,
        title: pform.title,
        status: pform.status as Project['status'],
        start_date: pform.start_date || undefined,
        end_date: pform.end_date || undefined,
        budget: pform.budget ? parseFloat(pform.budget) : undefined,
        notes: pform.notes || undefined,
      };
      if (editingProject) {
        await updateProject({ ...editingProject, ...data, status: data.status });
      } else {
        await addProject(data);
      }
      setShowProjectModal(false);
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to save project', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!confirmDelete) return;
    setDeleting(true);
    try {
      await removeProject(confirmDelete.id);
      setConfirmDelete(null);
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to delete project', 'error');
    } finally {
      setDeleting(false);
    }
  };

  const openMilestones = (projectId: string) => {
    setSelectedProject(selectedProject === projectId ? null : projectId);
    if (!milestones[projectId]) {
      loadMilestones(projectId);
    }
  };

  const handleAddMilestone = async () => {
    if (!selectedProject || !mform.title.trim()) return;
    setSaving(true);
    try {
      await addMilestone({
        project_id: selectedProject,
        title: mform.title,
        due_date: mform.due_date || undefined,
        completed: false,
        invoice_on_completion: mform.invoice_on_completion,
      });
      setMForm({ title: '', due_date: '', invoice_on_completion: false });
      setShowMilestoneModal(false);
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to add milestone', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handleToggleMilestone = async (m: Milestone, project: Project) => {
    try {
      if (!m.completed && m.invoice_on_completion) {
        setInvoicePrompt({ milestone: m, project });
        return;
      }
      await updateMilestone({ ...m, completed: !m.completed });
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to update milestone', 'error');
    }
  };

  const handleInvoicePromptYes = async () => {
    if (!invoicePrompt) return;
    const { milestone, project } = invoicePrompt;
    setInvoicePrompt(null);
    try {
      const projectMilestones = milestones[project.id] || [];
      const totalMs = projectMilestones.length || 1;
      const unitPrice = (project.budget || 0) / totalMs;
      await loadInvoices();
      const currentInvoices = useStore.getState().invoices;
      const invNumber = generateInvoiceNumber(currentInvoices);
      const dueDate = new Date();
      dueDate.setDate(dueDate.getDate() + 14);
      const lineItem = {
        id: crypto.randomUUID(),
        description: milestone.title,
        quantity: 1,
        unit_price: Math.round(unitPrice * 100) / 100,
        total: Math.round(unitPrice * 100) / 100,
      };
      await addInvoice({
        client_id: project.client_id,
        project_id: project.id,
        invoice_number: invNumber,
        status: 'draft',
        line_items: [lineItem],
        subtotal: lineItem.total,
        tax_rate: undefined,
        total: lineItem.total,
        due_date: dueDate.toISOString().split('T')[0],
        notes: `Generated from milestone: ${milestone.title}`,
      });
      await updateMilestone({ ...milestone, completed: true });
      addToast(`Invoice ${invNumber} created — review in Invoices`, 'success');
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to generate invoice from milestone', 'error');
    }
  };

  const handleInvoicePromptNo = async () => {
    if (!invoicePrompt) return;
    const { milestone } = invoicePrompt;
    setInvoicePrompt(null);
    try {
      await updateMilestone({ ...milestone, completed: true });
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to update milestone', 'error');
    }
  };

  const handleDeleteMilestone = async (id: string) => {
    try {
      await removeMilestone(id);
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to delete milestone', 'error');
    }
  };

  const getClientName = (clientId: string) => clients.find((c) => c.id === clientId)?.name || 'Unknown';

  const filtered = projects.filter(p => {
    if (!search) return true;
    const s = search.toLowerCase();
    return p.title.toLowerCase().includes(s) || getClientName(p.client_id).toLowerCase().includes(s);
  });

  const sorted = [...filtered].sort((a, b) => {
    const dir = sortDir === 'asc' ? 1 : -1;
    switch (sortKey) {
      case 'title': return dir * a.title.localeCompare(b.title);
      case 'client': return dir * getClientName(a.client_id).localeCompare(getClientName(b.client_id));
      case 'status': return dir * a.status.localeCompare(b.status);
      case 'budget': return dir * ((a.budget || 0) - (b.budget || 0));
      case 'date': return dir * (new Date(a.created_at).getTime() - new Date(b.created_at).getTime());
      default: return 0;
    }
  });

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortDir(d => d === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortDir('asc');
    }
  };

  if (loading) return (
    <div className="p-6">
      <div className="flex items-center justify-between mb-6">
        <div className="space-y-1">
          <div className="h-6 w-24 bg-[var(--bg-secondary)] rounded skeleton-pulse" />
          <div className="h-4 w-32 bg-[var(--bg-secondary)] rounded skeleton-pulse" />
        </div>
      </div>
      <div className="space-y-3">
        {[...Array(4)].map((_, i) => <div key={i} className="h-28 bg-[var(--bg-secondary)] rounded-[12px] skeleton-pulse" />)}
      </div>
    </div>
  );

  return (
    <div className="p-6">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-lg font-semibold text-[var(--text-primary)]">Projects</h2>
          <p className="text-sm text-[var(--text-secondary)] mt-0.5">
            {projects.filter((p) => p.status === 'active').length} active, {projects.length} total
          </p>
        </div>
        <Button onClick={openNewProject} size="sm" disabled={clients.length === 0}>
          <Plus size={14} />
          New Project
        </Button>
      </div>

      <div className="flex items-center gap-3 mb-4">
        <div className="relative flex-1 max-w-xs">
          <Search size={13} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[var(--text-tertiary)]" />
          <input
            type="text"
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search projects..."
            className="w-full pl-8 pr-3 py-1.5 text-xs border border-[var(--border-color)] rounded-[6px] placeholder:text-[var(--text-tertiary)] focus:outline-none focus:border-[var(--accent)] bg-[var(--bg-secondary)]"
          />
        </div>
        <div className="flex items-center gap-1">
          <span className="text-[10px] text-[var(--text-tertiary)]">Sort:</span>
          {(['date', 'title', 'client', 'status', 'budget'] as SortKey[]).map(k => (
            <button
              key={k}
              onClick={() => toggleSort(k)}
              className={`text-[10px] px-2 py-0.5 rounded-[4px] transition-colors capitalize ${
                sortKey === k ? 'bg-[var(--accent-bg)] text-[var(--accent)] font-medium' : 'text-[var(--text-tertiary)] hover:text-[var(--text-primary)]'
              }`}
            >
              {k}
              {sortKey === k && <span className="ml-0.5">{sortDir === 'asc' ? '↑' : '↓'}</span>}
            </button>
          ))}
        </div>
      </div>

      {clients.length === 0 && (
        <Card className="mb-4 border-[#FAEEDA] bg-[#FAEEDA]/50">
          <p className="text-sm text-[#854F0B]">
            Add at least one client before creating a project.
          </p>
        </Card>
      )}

      {projects.length === 0 ? (
        <Card className="text-center py-16 flex flex-col items-center">
          <FolderKanban size={40} className="text-[var(--text-tertiary)] mb-4" />
          <h3 className="text-[15px] font-medium text-[var(--text-secondary)] mb-1.5">No projects yet</h3>
          <p className="text-[13px] text-[var(--text-tertiary)] max-w-xs mb-5">Create your first project to start tracking work.</p>
          <Button onClick={openNewProject} size="sm" variant="secondary">New Project</Button>
        </Card>
      ) : filtered.length === 0 && search ? (
        <Card className="text-center py-12">
          <p className="text-sm text-[var(--text-tertiary)]">No projects match "{search}"</p>
        </Card>
      ) : (
        <div className="space-y-3">
          {sorted.map((project) => {
            const projectMilestones = milestones[project.id] || [];
            const completedMs = projectMilestones.filter((m) => m.completed).length;
            const totalMs = projectMilestones.length;
            return (
              <div key={project.id}>
                <Card className="flex items-start justify-between">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <h3 className="text-sm font-semibold text-[var(--text-primary)]">{project.title}</h3>
                      <Badge variant={statusBadge[project.status] || 'default'}>{project.status}</Badge>
                    </div>
                    <p className="text-xs text-[var(--text-secondary)] mb-2">{getClientName(project.client_id)}</p>
                    <div className="flex items-center gap-4 text-xs text-[var(--text-tertiary)] mb-2">
                      {project.start_date && (
                        <span className="flex items-center gap-1">
                          <Calendar size={12} />
                          {relativeDate(project.start_date)}
                        </span>
                      )}
                      {project.budget && (
                        <span className="flex items-center gap-1">
                          <DollarSign size={12} />
                          {formatCurrency(project.budget, profile?.currency)}
                        </span>
                      )}
                    </div>
                    {totalMs > 0 && (
                      <div className="w-48">
                        <ProgressBar value={completedMs} max={totalMs} label={`${completedMs}/${totalMs} milestones`} size="sm" />
                      </div>
                    )}
                  </div>
                  <div className="flex items-center gap-1 flex-shrink-0 ml-3">
                    <button
                      onClick={() => openMilestones(project.id)}
                      aria-label="Expand milestones"
                      className={`p-1.5 rounded-[8px] transition-colors ${selectedProject === project.id ? 'text-[var(--accent)] bg-[var(--accent-bg)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-secondary)]'}`}
                    >
                      <ChevronRight size={14} className={`transition-transform ${selectedProject === project.id ? 'rotate-90' : ''}`} />
                    </button>
                    <button
                      onClick={() => openEditProject(project)}
                      aria-label="Edit project"
                      className="p-1.5 rounded-[8px] text-[var(--text-tertiary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-secondary)] transition-colors"
                    >
                      <Pencil size={14} />
                    </button>
                    <button
                      onClick={() => setConfirmDelete({ id: project.id, title: project.title })}
                      aria-label="Delete project"
                      className="p-1.5 rounded-[8px] text-[var(--text-tertiary)] hover:text-[#A32D2D] hover:bg-[#FCEBEB] transition-colors"
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                </Card>

                {selectedProject === project.id && (
                  <div className="ml-4 mt-2 space-y-2 mb-3">
                    <div className="flex items-center justify-between">
                      <span className="text-xs font-medium text-[var(--text-secondary)]">Milestones</span>
                      <button
                        onClick={() => { setShowMilestoneModal(true); setMForm({ title: '', due_date: '', invoice_on_completion: false }); }}
                        className="text-xs text-[var(--accent)] hover:underline"
                      >
                        + Add
                      </button>
                    </div>
                    {projectMilestones.length === 0 ? (
                      <p className="text-xs text-[var(--text-tertiary)] pl-2">No milestones yet. Add one to track progress.</p>
                    ) : (
                      projectMilestones.map((m) => (
                        <div key={m.id} className="flex items-center gap-2 pl-2">
                          <button onClick={() => handleToggleMilestone(m, project)} aria-label="Toggle milestone" className="flex-shrink-0">
                            {m.completed ? (
                              <CheckCircle2 size={16} className="text-[var(--accent)]" />
                            ) : (
                              <Circle size={16} className="text-[#D4D4D2]" />
                            )}
                          </button>
                          <span className={`text-xs flex-1 ${m.completed ? 'line-through text-[var(--text-tertiary)]' : 'text-[var(--text-primary)]'}`}>
                            {m.title}
                          </span>
                          {m.invoice_on_completion && (
                            <Badge variant="info">invoice</Badge>
                          )}
                          {m.due_date && (
                            <span className="text-[10px] text-[var(--text-tertiary)]">{relativeDate(m.due_date)}</span>
                          )}
                          {invoicePrompt?.milestone.id === m.id && (
                            <div className="flex items-center gap-1 ml-1">
                              <button onClick={handleInvoicePromptYes} className="text-[10px] px-1.5 py-0.5 rounded-[6px] bg-[var(--accent)] text-white font-medium">Yes</button>
                              <button onClick={handleInvoicePromptNo} className="text-[10px] px-1.5 py-0.5 rounded-[6px] bg-[var(--bg-secondary)] text-[var(--text-secondary)] font-medium">Skip</button>
                            </div>
                          )}
                          <button onClick={() => handleDeleteMilestone(m.id)} aria-label="Delete milestone" className="text-[var(--text-tertiary)] hover:text-[#A32D2D]">
                            <Trash2 size={12} />
                          </button>
                        </div>
                      ))
                    )}
                    {invoicePrompt && (
                      <div className="pl-2">
                        <p className="text-xs text-[#854F0B]">Generate invoice for this milestone?</p>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      <Modal open={showProjectModal} onClose={() => setShowProjectModal(false)} title={editingProject ? 'Edit Project' : 'New Project'} size="md">
        <div className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Client *</label>
            <ClientSelect
              clients={clients}
              value={pform.client_id}
              onChange={(clientId) => setPForm({ ...pform, client_id: clientId })}
              placeholder="Select a client..."
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Title *</label>
            <input
              type="text"
              value={pform.title}
              onChange={(e) => setPForm({ ...pform, title: e.target.value })}
              placeholder="Project title"
              className="w-full px-3 py-2 text-sm border border-[var(--border-color)] rounded-[8px] placeholder:text-[var(--text-tertiary)] focus:outline-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/20"
              autoFocus
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Status</label>
              <select
                value={pform.status}
                onChange={(e) => setPForm({ ...pform, status: e.target.value })}
                className="w-full px-3 py-2 text-sm border border-[var(--border-color)] rounded-[8px] focus:outline-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/20"
              >
                <option value="active">Active</option>
                <option value="paused">Paused</option>
                <option value="completed">Completed</option>
                <option value="cancelled">Cancelled</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Budget</label>
              <input
                type="number"
                value={pform.budget}
                onChange={(e) => setPForm({ ...pform, budget: e.target.value })}
                placeholder="0.00"
                className="w-full px-3 py-2 text-sm border border-[var(--border-color)] rounded-[8px] placeholder:text-[var(--text-tertiary)] focus:outline-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/20"
              />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Start Date</label>
              <input
                type="date"
                value={pform.start_date}
                onChange={(e) => setPForm({ ...pform, start_date: e.target.value })}
                className="w-full px-3 py-2 text-sm border border-[var(--border-color)] rounded-[8px] focus:outline-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/20"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">End Date</label>
              <input
                type="date"
                value={pform.end_date}
                onChange={(e) => setPForm({ ...pform, end_date: e.target.value })}
                className="w-full px-3 py-2 text-sm border border-[var(--border-color)] rounded-[8px] focus:outline-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/20"
              />
            </div>
          </div>
          <div>
            <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Notes</label>
            <textarea
              value={pform.notes}
              onChange={(e) => setPForm({ ...pform, notes: e.target.value })}
              placeholder="Project notes..."
              rows={2}
              className="w-full px-3 py-2 text-sm border border-[var(--border-color)] rounded-[8px] placeholder:text-[var(--text-tertiary)] focus:outline-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/20 resize-none"
            />
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="secondary" onClick={() => setShowProjectModal(false)} size="sm">Cancel</Button>
            <Button onClick={handleSaveProject} loading={saving} disabled={!pform.title.trim() || !pform.client_id} size="sm">
              {editingProject ? 'Save Changes' : 'Create Project'}
            </Button>
          </div>
        </div>
      </Modal>

      <Modal open={showMilestoneModal} onClose={() => setShowMilestoneModal(false)} title="Add Milestone" size="sm">
        <div className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Title *</label>
            <input
              type="text"
              value={mform.title}
              onChange={(e) => setMForm({ ...mform, title: e.target.value })}
              placeholder="Milestone name"
              className="w-full px-3 py-2 text-sm border border-[var(--border-color)] rounded-[8px] placeholder:text-[var(--text-tertiary)] focus:outline-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/20"
              autoFocus
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Due Date</label>
            <input
              type="date"
              value={mform.due_date}
              onChange={(e) => setMForm({ ...mform, due_date: e.target.value })}
              className="w-full px-3 py-2 text-sm border border-[var(--border-color)] rounded-[8px] focus:outline-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/20"
            />
          </div>
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={mform.invoice_on_completion}
              onChange={(e) => setMForm({ ...mform, invoice_on_completion: e.target.checked })}
              className="w-4 h-4 rounded border-[#D4D4D2] text-[var(--accent)] focus:ring-[var(--accent)]"
            />
            <span className="text-xs text-[var(--text-secondary)]">Trigger invoice on completion</span>
          </label>
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="secondary" onClick={() => setShowMilestoneModal(false)} size="sm">Cancel</Button>
            <Button onClick={handleAddMilestone} loading={saving} disabled={!mform.title.trim()} size="sm">Add Milestone</Button>
          </div>
        </div>
      </Modal>

      <ConfirmDialog
        open={!!confirmDelete}
        onClose={() => setConfirmDelete(null)}
        onConfirm={handleDelete}
        title="Delete Project"
        message={`Are you sure you want to delete "${confirmDelete?.title}"? This cannot be undone.`}
        confirmLabel="Delete"
        variant="danger"
        loading={deleting}
      />
    </div>
  );
}

import { useEffect, useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useStore } from '../store';
import type { Proposal } from '../types';
import Button from '../components/ui/Button';
import Card from '../components/ui/Card';
import Badge from '../components/ui/Badge';
import ConfirmDialog from '../components/ui/ConfirmDialog';
import { exportProposalPDF, exportProposalDOCX } from '../export';
import { formatCurrency } from '../utils/format';
import { htmlToPlainText } from '../utils/htmlToText';
import { useToasts } from '../store/toastStore';
import { checkAndNotify, tryUnlock } from '../achievements/notify';
import { Plus, Trash2, Send, Eye, Download, FileText, Search, ArrowUpDown, Bell, Check, X } from 'lucide-react';
import { generateFollowUpDraft } from '../utils/followUpTemplates';

const statusBadge: Record<string, 'success' | 'warning' | 'danger' | 'info'> = {
  draft: 'warning',
  sent: 'info',
  accepted: 'success',
  declined: 'danger',
};

function generateContractBody(
  freelancerName: string,
  clientName: string,
  proposalTitle: string,
  scope: string,
  timeline: string,
  formattedRate: string
): string {
  return [
    'SERVICE AGREEMENT', '',
    `This agreement is between ${freelancerName} ("Contractor") and ${clientName} ("Client").`, '',
    'PROJECT', proposalTitle, '',
    'SCOPE OF WORK', scope, '',
    'TIMELINE', timeline || 'As agreed upon by both parties.', '',
    'COMPENSATION', formattedRate, 'Payment is due within 14 days of invoice.', '',
    'REVISIONS', 'This agreement includes up to 2 rounds of revisions. Additional revisions will be quoted separately.', '',
    'KILL FEE', 'If the Client cancels the project after work has begun, a kill fee of 25% of the total project value is due immediately.', '',
    'INTELLECTUAL PROPERTY', 'All intellectual property created under this agreement transfers to the Client upon receipt of final payment.', '',
    'CONFIDENTIALITY', 'Both parties agree to keep the terms of this agreement and any shared materials confidential.', '',
    'Agreed by:', '',
    `${freelancerName}                    ${clientName}`,
    'Date: ___________                   Date: ___________',
  ].join('\n');
}

type SortKey = 'title' | 'client' | 'status' | 'date';

export default function Proposals() {
  const { proposals, loadProposals, clients, loadClients, updateProposal, removeProposal, profile, loadProfile, addContract, pendingFollowUps, loadPendingFollowUps, updateFollowUpStatus, followUpSettings } = useStore();
  const addToast = useToasts((s) => s.add);
  const navigate = useNavigate();
  const [expanded, setExpanded] = useState<string | null>(null);
  const [exportDropdown, setExportDropdown] = useState<string | null>(null);
  const [convertingId, setConvertingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const dropdownRef = useRef<HTMLDivElement | null>(null);
  const [search, setSearch] = useState('');
  const [sortKey, setSortKey] = useState<SortKey>('date');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('desc');
  const [confirmDelete, setConfirmDelete] = useState<{ id: string; title: string } | null>(null);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    Promise.all([loadProposals(), loadClients(), loadProfile()])
      .catch(err => addToast(err?.toString?.() || 'Failed to load', 'error'))
      .finally(() => setLoading(false));
    loadPendingFollowUps();
  }, [loadProposals, loadClients, loadProfile, loadPendingFollowUps]);

  useEffect(() => {
    if (!exportDropdown) return;
    const handler = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setExportDropdown(null);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [exportDropdown]);

  const handleSend = async (p: Proposal) => {
    try {
      await updateProposal({ ...p, status: 'sent' as const });
      checkAndNotify(useStore.getState(), addToast);
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to send', 'error');
    }
  };

  const handleExportPDF = (p: Proposal) => {
    const client = getClient(p.client_id);
    if (client && profile) {
      exportProposalPDF(p, client, profile);
      tryUnlock('first_export', addToast);
    }
    setExportDropdown(null);
  };

  const handleDelete = async () => {
    if (!confirmDelete) return;
    setDeleting(true);
    try {
      await removeProposal(confirmDelete.id);
      setConfirmDelete(null);
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to delete', 'error');
    } finally {
      setDeleting(false);
    }
  };

  const handleAccept = async (p: Proposal) => {
    try {
      await updateProposal({ ...p, status: 'accepted' as const });
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to accept', 'error');
    }
  };

  const getClient = (clientId: string) => clients.find((c) => c.id === clientId);
  const getClientName = (clientId: string) => getClient(clientId)?.name || 'Unknown';

  const handleConvertToContract = async (p: Proposal) => {
    const client = getClient(p.client_id);
    if (!client || !profile) return;
    setConvertingId(p.id);
    try {
      const freelancerName = profile.name || 'Freelancer';
      const rateStr = p.rate
        ? formatCurrency(p.rate, profile.currency) + (p.rate_type === 'hourly' ? ' per hour' : ' flat project fee')
        : 'TBD';
      const body = generateContractBody(freelancerName, client.name, p.title, p.scope || '', p.timeline || '', rateStr);
      await addContract({ client_id: p.client_id, proposal_id: p.id, title: `Contract — ${p.title}`, status: 'draft', body });
      navigate('/contracts');
    } catch (err) {
      addToast(err?.toString?.() || 'Failed to convert to contract', 'error');
    } finally {
      setConvertingId(null);
    }
  };

  const handleExportDOCX = (p: Proposal) => {
    const client = getClient(p.client_id);
    if (client && profile) {
      exportProposalDOCX(p, client, profile);
      tryUnlock('first_export', addToast);
    }
    setExportDropdown(null);
  };

  const formatRate = (p: Proposal) => {
    if (!p.rate || !profile) return '';
    const formatted = formatCurrency(p.rate, profile.currency);
    if (p.rate_type === 'hourly') return `${formatted}/hr`;
    return `${formatted} flat`;
  };

  const filtered = proposals.filter(p => {
    if (!search) return true;
    const s = search.toLowerCase();
    return p.title.toLowerCase().includes(s) || getClientName(p.client_id).toLowerCase().includes(s);
  });

  const sorted = [...filtered].sort((a, b) => {
    const dir = sortDir === 'asc' ? 1 : -1;
    switch (sortKey) {
      case 'title': return dir * a.title.localeCompare(b.title);
      case 'client': return dir * getClientName(a.client_id).localeCompare(getClientName(b.client_id));
      case 'status': return dir * a.status.localeCompare(b.status);
      case 'date': return dir * (new Date(a.created_at).getTime() - new Date(b.created_at).getTime());
      default: return 0;
    }
  });

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) { setSortDir(d => d === 'asc' ? 'desc' : 'asc'); }
    else { setSortKey(key); setSortDir('asc'); }
  };

  if (loading) return (
    <div className="p-6">
      <div className="flex items-center justify-between mb-6">
        <div className="h-6 w-24 bg-[var(--bg-secondary)] rounded skeleton-pulse" />
      </div>
      <div className="space-y-3">
        {[...Array(4)].map((_, i) => <div key={i} className="h-32 bg-[var(--bg-secondary)] rounded-[12px] skeleton-pulse" />)}
      </div>
    </div>
  );

  return (
    <div className="p-6">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-lg font-semibold text-[var(--text-primary)]">Proposals</h2>
          <p className="text-sm text-[var(--text-secondary)] mt-0.5">
            {proposals.filter((p) => p.status === 'draft').length} drafts, {proposals.length} total
          </p>
        </div>
        <Button onClick={() => navigate('/proposals/new')} size="sm" disabled={clients.length === 0}>
          <Plus size={14} />
          New Proposal
        </Button>
      </div>

      <div className="flex items-center gap-3 mb-4">
        <div className="relative flex-1 max-w-xs">
          <Search size={13} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[var(--text-tertiary)]" />
          <input
            type="text" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search proposals..."
            className="w-full pl-8 pr-3 py-1.5 text-xs border border-[var(--border-color)] rounded-[6px] placeholder:text-[var(--text-tertiary)] focus:outline-none focus:border-[var(--accent)] bg-[var(--bg-secondary)]"
          />
        </div>
        <div className="flex items-center gap-1">
          <span className="text-[10px] text-[var(--text-tertiary)]">Sort:</span>
          {(['date', 'title', 'client', 'status'] as SortKey[]).map(k => (
            <button key={k} onClick={() => toggleSort(k)} className={`text-[10px] px-2 py-0.5 rounded-[4px] transition-colors capitalize ${sortKey === k ? 'bg-[var(--accent-bg)] text-[var(--accent)] font-medium' : 'text-[var(--text-tertiary)] hover:text-[var(--text-primary)]'}`}>
              {k}{sortKey === k && <span className="ml-0.5">{sortDir === 'asc' ? '↑' : '↓'}</span>}
            </button>
          ))}
        </div>
      </div>

      {clients.length === 0 ? (
        <Card className="mb-4 border-[#FAEEDA] bg-[#FAEEDA]/50">
          <p className="text-sm text-[#854F0B]">Add at least one client before creating a proposal.</p>
        </Card>
      ) : proposals.length === 0 ? (
        <Card className="text-center py-16 flex flex-col items-center">
          <FileText size={40} className="text-[var(--text-tertiary)] mb-4" />
          <h3 className="text-[15px] font-medium text-[var(--text-secondary)] mb-1.5">No proposals yet</h3>
          <p className="text-[13px] text-[var(--text-tertiary)] max-w-xs mb-5">Create your first proposal to start winning work.</p>
          <Button onClick={() => navigate('/proposals/new')} size="sm" variant="secondary">New Proposal</Button>
        </Card>
      ) : filtered.length === 0 && search ? (
        <Card className="text-center py-12"><p className="text-sm text-[var(--text-tertiary)]">No proposals match "{search}"</p></Card>
      ) : (
        <div className="space-y-3">
          {sorted.map((p) => (
            <Card key={p.id}>
              <div className="flex items-start justify-between">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className="text-sm font-semibold text-[var(--text-primary)]">{p.title}</h3>
                    <Badge variant={statusBadge[p.status]}>{p.status}</Badge>
                  </div>
                  <div className="flex items-center gap-3 text-xs text-[var(--text-secondary)] mb-2">
                    <span>{getClientName(p.client_id)}</span>
                    {formatRate(p) && <span>{formatRate(p)}</span>}
                    {p.timeline && <span>{p.timeline}</span>}
                  </div>
                  {p.scope && (
                    <p className="text-xs text-[var(--text-tertiary)] line-clamp-2 mb-2">{p.scope}</p>
                  )}
                  {p.status === 'accepted' && (
                    <button
                      onClick={() => handleConvertToContract(p)}
                      disabled={convertingId === p.id}
                      className="inline-flex items-center gap-1.5 text-xs font-medium text-white bg-[var(--accent)] hover:bg-[var(--accent-hover)] px-3 py-1.5 rounded-[8px] transition-colors disabled:opacity-50"
                    >
                      <FileText size={13} />
                      {convertingId === p.id ? 'Creating...' : 'Convert to contract'}
                    </button>
                  )}
                </div>
                <div className="flex items-center gap-1 flex-shrink-0 ml-3">
                  {p.status === 'draft' && (
                    <button onClick={() => handleSend(p)} aria-label="Send proposal" className="p-1.5 rounded-[8px] text-[var(--accent)] hover:bg-[var(--accent-bg)] transition-colors" title="Send">
                      <Send size={14} />
                    </button>
                  )}
                  {p.status === 'sent' && (
                    <button onClick={() => handleAccept(p)} aria-label="Accept proposal" className="p-1.5 rounded-[8px] text-[var(--accent)] hover:bg-[var(--accent-bg)] transition-colors" title="Accept">
                      <Send size={14} />
                    </button>
                  )}
                  <div className="relative" ref={exportDropdown === p.id ? dropdownRef : undefined}>
                    <button onClick={() => setExportDropdown(exportDropdown === p.id ? null : p.id)} aria-label="Export proposal" className="p-1.5 rounded-[8px] text-[var(--text-tertiary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-secondary)] transition-colors" title="Export">
                      <Download size={14} />
                    </button>
                    {exportDropdown === p.id && (
                      <div className="absolute right-0 top-full mt-1 bg-[var(--bg-card)] border border-[var(--border-color)] rounded-[8px] shadow-lg py-1 z-10 w-28">
                        <button onClick={() => handleExportPDF(p)} className="w-full text-left px-3 py-1.5 text-xs text-[var(--text-primary)] hover:bg-[var(--bg-secondary)] transition-colors">PDF</button>
                        <button onClick={() => handleExportDOCX(p)} className="w-full text-left px-3 py-1.5 text-xs text-[var(--text-primary)] hover:bg-[var(--bg-secondary)] transition-colors">DOCX</button>
                      </div>
                    )}
                  </div>
                  <button onClick={() => setExpanded(expanded === p.id ? null : p.id)} aria-label="View proposal body" className={`p-1.5 rounded-[8px] transition-colors ${expanded === p.id ? 'text-[var(--accent)] bg-[var(--accent-bg)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-secondary)]'}`} title="View body">
                    <Eye size={14} />
                  </button>
                  <button onClick={() => setConfirmDelete({ id: p.id, title: p.title })} aria-label="Delete proposal" className="p-1.5 rounded-[8px] text-[var(--text-tertiary)] hover:text-[#A32D2D] hover:bg-[#FCEBEB] transition-colors">
                    <Trash2 size={14} />
                  </button>
                </div>
              </div>
              {expanded === p.id && (
                <div className="mt-3 pt-3 border-t border-[var(--border-color)] space-y-3">
                  {/* Follow-up banner */}
                  {(() => {
                    const fu = pendingFollowUps.find((f) => f.entity_type === 'proposal' && f.entity_id === p.id);
                    if (fu && p.status === 'sent') {
                      const client = getClient(p.client_id);
                      const sentDate = p.sent_at ? new Date(p.sent_at) : new Date(p.created_at);
                      const daysElapsed = Math.floor((Date.now() - sentDate.getTime()) / 86400000);
                      const templateKey = daysElapsed >= 10 ? 'proposal_day14' : daysElapsed >= 4 ? 'proposal_day7' : 'proposal_day3';
                      const draft = generateFollowUpDraft(templateKey, {
                        clientName: client?.name || 'Unknown',
                        proposalTitle: p.title,
                        daysElapsed,
                        projectName: p.title,
                        freelancerName: profile?.name || 'Freelancer',
                      }, followUpSettings.templates);
                      return (
                        <div className="px-3 py-2.5 rounded-[8px] bg-[var(--accent-bg)]/30 border border-[var(--accent)]/20">
                          <div className="flex items-center gap-1.5 mb-1.5">
                            <Bell size={12} className="text-[var(--accent)]" />
                            <span className="text-[10px] font-semibold text-[var(--accent)] uppercase tracking-wide">Follow-up Draft — Stage {fu.stage}</span>
                            <span className="text-[10px] text-[var(--text-tertiary)]">{daysElapsed}d since sent</span>
                          </div>
                          <textarea
                            value={draft}
                            onChange={() => {}}
                            rows={5}
                            className="w-full px-2.5 py-1.5 text-xs border border-[var(--border-color)] rounded-[6px] bg-[var(--bg-card)] text-[var(--text-primary)] resize-none leading-relaxed mb-2"
                          />
                          <div className="flex items-center gap-1.5">
                            <button
                              onClick={async () => {
                                await navigator.clipboard.writeText(draft);
                                await updateFollowUpStatus(fu.id, 'sent', 'sent');
                                addToast('Copied to clipboard', 'success');
                              }}
                              className="flex items-center gap-1 px-2 py-1 text-[10px] font-medium text-white bg-[var(--accent)] hover:bg-[var(--accent-hover)] rounded-[6px] transition-colors"
                            >
                              <Send size={10} /> Send
                            </button>
                            <button
                              onClick={async () => { await updateFollowUpStatus(fu.id, 'dismissed', 'dismissed'); addToast('Follow-up dismissed', 'info'); }}
                              className="flex items-center gap-1 px-2 py-1 text-[10px] text-[var(--text-secondary)] hover:text-[var(--text-primary)] rounded-[6px] hover:bg-[var(--bg-secondary)] transition-colors"
                            >
                              <X size={10} /> Dismiss
                            </button>
                            <button
                              onClick={async () => { await updateFollowUpStatus(fu.id, 'responded', 'responded_to'); addToast('Marked as responded', 'success'); }}
                              className="flex items-center gap-1 px-2 py-1 text-[10px] text-[var(--accent)] hover:bg-[var(--accent-bg)] rounded-[6px] transition-colors ml-auto"
                            >
                              <Check size={10} /> Mark Responded
                            </button>
                          </div>
                        </div>
                      );
                    }
                    return null;
                  })()}
                  {p.body && (
                    <p className="text-xs text-[var(--text-primary)] whitespace-pre-wrap leading-relaxed">{htmlToPlainText(p.body)}</p>
                  )}
                </div>
              )}
            </Card>
          ))}
        </div>
      )}

      <ConfirmDialog
        open={!!confirmDelete}
        onClose={() => setConfirmDelete(null)}
        onConfirm={handleDelete}
        title="Delete Proposal"
        message={`Are you sure you want to delete "${confirmDelete?.title}"? This cannot be undone.`}
        confirmLabel="Delete"
        variant="danger"
        loading={deleting}
      />
    </div>
  );
}

import { useEffect, useState, useCallback, useRef } from 'react';
import { useStore } from '../store';
import type { UserProfile, ExportTemplate } from '../types';
import Card from '../components/ui/Card';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import ConfirmDialog from '../components/ui/ConfirmDialog';
import { useToasts } from '../store/toastStore';
import { save } from '@tauri-apps/plugin-dialog';
import { readTextFile, writeFile } from '@tauri-apps/plugin-fs';
import { open } from '@tauri-apps/plugin-dialog';
import { Check, Upload, Download, AlertTriangle, Trash2, Lock, Sparkles, ExternalLink, Bell, Eye, ArrowRight, FileText } from 'lucide-react';
import { THEMES, applyTheme, getTheme } from '../themes/themes';
import type { ThemeId } from '../themes';
import { PROFESSION_THEME, type Profession } from '../themes';
import { getArchetype, ARCHETYPE_LIST } from '../archetypes';
import { getUnlockedThemes, getUnlockedAchievementKeys } from '../achievements/checker';
import { TEMPLATE_LABELS } from '../utils/followUpTemplates';

const currencies = ['CAD', 'USD', 'GBP', 'EUR', 'AUD'];
const writingStyles = ['professional', 'warm', 'direct', 'bold'];

const ACCENT_COLORS = [
  { id: 'sage', label: 'Sage', hex: '#1EC98A' },
  { id: 'amber', label: 'Amber', hex: '#F59E0B' },
  { id: 'rose', label: 'Rose', hex: '#E11D48' },
  { id: 'sky', label: 'Sky', hex: '#0EA5E9' },
  { id: 'violet', label: 'Violet', hex: '#8B5CF6' },
  { id: 'teal', label: 'Teal', hex: '#14B8A6' },
  { id: 'orange', label: 'Orange', hex: '#F97316' },
  { id: 'slate', label: 'Slate', hex: '#64748B' },
];

function labelForStyle(s: string): string {
  const map: Record<string, string> = {
    professional: 'Professional',
    warm: 'Warm & personal',
    direct: 'Direct & concise',
    bold: 'Bold & confident',
  };
  return map[s] || s;
}

export default function Settings() {
  const { profile, loadProfile, saveProfile, isLicensed, activateLicense, removeLicense, followUpSettings, loadFollowUpSettings, saveFollowUpSettings } = useStore();
  const addToast = useToasts((s) => s.add);
  const [saved, setSaved] = useState<Set<string>>(new Set());
  const [showResetModal, setShowResetModal] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showLicenseModal, setShowLicenseModal] = useState(false);
  const [licenseKey, setLicenseKey] = useState('');
  const [licenseError, setLicenseError] = useState('');
  const [licenseActivating, setLicenseActivating] = useState(false);
  const [showRemoveLicenseConfirm, setShowRemoveLicenseConfirm] = useState(false);
  const [activeTheme, setActiveTheme] = useState<ThemeId>('default');
  const [unlockedThemes, setUnlockedThemes] = useState<Set<string>>(new Set(['default']));
  const [fuEnabled, setFuEnabled] = useState(true);
  const [fuProposalDelay, setFuProposalDelay] = useState(3);
  const [fuInvoiceDelay, setFuInvoiceDelay] = useState(0);
  const [fuTemplates, setFuTemplates] = useState<Record<string, string>>({});
  const [fuPreview, setFuPreview] = useState<string | null>(null);
  const fuInitRef = useRef(false);
  const [density, setDensity] = useState<string>('comfortable');
  const [accentColor, setAccentColor] = useState<string>('sage');
  const [unlockedAchievements, setUnlockedAchievements] = useState<Set<string>>(new Set());
  const densityInitRef = useRef(false);
  const accentInitRef = useRef(false);
  const [form, setForm] = useState<UserProfile>({
    name: '',
    email: '',
    currency: 'CAD',
    hourly_rate: undefined,
    tax_rate: undefined,
    payment_terms: 14,
    writing_style: 'professional',
    writing_voice: '',
    tagline: '',
    always_include: '',
    theme: 'light',
    ai_enabled: false,
  });
  const timers = useRef<Record<string, ReturnType<typeof setTimeout>>>({});
  const formInitialized = useRef(false);

  useEffect(() => {
    loadProfile()
      .catch(err => addToast(err?.toString?.() || 'Failed to load profile', 'error'))
      .finally(() => setLoading(false));
  }, [loadProfile]);

  useEffect(() => {
    if (profile && !formInitialized.current) {
      formInitialized.current = true;
      setForm({
        name: profile.name || '',
        email: profile.email || '',
        currency: profile.currency || 'CAD',
        hourly_rate: profile.hourly_rate,
        tax_rate: profile.tax_rate,
        payment_terms: profile.payment_terms ?? 14,
        writing_style: profile.writing_style || 'professional',
        writing_voice: profile.writing_voice || '',
        tagline: profile.tagline || '',
        always_include: profile.always_include || '',
        theme: profile.theme || 'light',
        license_key: profile.license_key,
        licensed_at: profile.licensed_at,
        ai_enabled: profile.ai_enabled ?? false,
      });
    }
  }, [profile]);

  useEffect(() => {
    const stored = (localStorage.getItem('lance:theme') || 'default') as ThemeId;
    setActiveTheme(stored);
    if (isLicensed) {
      setUnlockedThemes(new Set(['default', 'studio', 'terminal', 'craft', 'motion', 'lens', 'scale']));
    } else {
      Promise.all([getUnlockedThemes(), getUnlockedAchievementKeys()]).then(([unlocked, achievementKeys]) => {
        const set = new Set(['default', ...unlocked]);
        const prof = profile?.profession as Profession | undefined;
        if (prof && PROFESSION_THEME[prof]) {
          set.add(PROFESSION_THEME[prof]);
        }
        setUnlockedThemes(set);
        setUnlockedAchievements(new Set(achievementKeys));
      });
    }
  }, [isLicensed, profile?.profession]);

  // Load density and accent from localStorage
  useEffect(() => {
    if (!densityInitRef.current) {
      densityInitRef.current = true;
      const saved = localStorage.getItem('lance:density') || 'comfortable';
      setDensity(saved);
      if (saved === 'compact') {
        document.body.classList.add('density-compact');
      }
    }
  }, []);

  useEffect(() => {
    if (!accentInitRef.current) {
      accentInitRef.current = true;
      const saved = localStorage.getItem('lance:accent-color');
      if (saved) {
        setAccentColor(saved);
        applyAccentColor(saved);
      }
    }
  }, []);

  // Load follow-up settings
  useEffect(() => {
    loadFollowUpSettings();
  }, []);

  useEffect(() => {
    if (!fuInitRef.current && followUpSettings.templates && Object.keys(followUpSettings.templates).length > 0) {
      fuInitRef.current = true;
      setFuEnabled(followUpSettings.enabled);
      setFuProposalDelay(followUpSettings.proposal_delay_days);
      setFuInvoiceDelay(followUpSettings.invoice_delay_days);
      setFuTemplates({ ...followUpSettings.templates });
    }
  }, [followUpSettings]);

  useEffect(() => {
    if (form.theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [form.theme]);

  const autoSave = useCallback(
    (updates: Partial<UserProfile>, section: string) => {
      const newProfile = { ...form, ...updates };
      setForm(newProfile);
      try {
        saveProfile(newProfile);
      } catch (err) {
        addToast(err?.toString?.() || 'Failed to save', 'error');
      }
      setSaved((prev) => new Set([...prev, section]));
      if (timers.current[section]) clearTimeout(timers.current[section]);
      timers.current[section] = setTimeout(() => {
        setSaved((prev) => {
          const next = new Set(prev);
          next.delete(section);
          return next;
        });
      }, 1500);
    },
    [form, saveProfile, addToast]
  );

  const applyAccentColor = (colorId: string) => {
    const acc = ACCENT_COLORS.find((c) => c.id === colorId);
    if (!acc) return;
    document.body.classList.forEach((cls) => {
      if (cls.startsWith('accent-')) document.body.classList.remove(cls);
    });
    document.body.classList.add(`accent-${colorId}`);
    const root = document.documentElement;
    root.style.setProperty('--accent', acc.hex);
  };

  const handleDensityChange = (newDensity: string) => {
    setDensity(newDensity);
    if (newDensity === 'compact') {
      document.body.classList.add('density-compact');
    } else {
      document.body.classList.remove('density-compact');
    }
    localStorage.setItem('lance:density', newDensity);
  };

  const handleAccentChange = (colorId: string) => {
    setAccentColor(colorId);
    applyAccentColor(colorId);
    localStorage.setItem('lance:accent-color', colorId);
  };

  const handleExportData = async () => {
    try {
      const data: Record<string, unknown[]> = {};
      const { invoke: tauriInvoke } = await import('@tauri-apps/api/core');
      data.clients = await tauriInvoke('get_clients');
      data.projects = await tauriInvoke('get_projects');
      data.proposals = await tauriInvoke('get_proposals');
      data.contracts = await tauriInvoke('get_contracts');
      data.time_entries = await tauriInvoke('get_time_entries');
      data.invoices = await tauriInvoke('get_invoices');
      data.expenses = await tauriInvoke('get_expenses');
      data.user_profile = profile ? [profile] : [];

      const json = JSON.stringify(data, null, 2);
      const filePath = await save({ defaultPath: `Lance_Backup_${new Date().toISOString().split('T')[0]}.json` });
      if (!filePath) return;
      await writeFile(filePath, new TextEncoder().encode(json));
      addToast('Data exported successfully', 'success');
    } catch {
      addToast('Export failed', 'error');
    }
  };

  const handleImportData = async () => {
    try {
      const filePath = await open({
        filters: [{ name: 'JSON', extensions: ['json'] }],
      });
      if (!filePath) return;
      const content = await readTextFile(filePath);
      const data = JSON.parse(content);

      const { invoke: tauriInvoke } = await import('@tauri-apps/api/core');

      if (data.user_profile?.[0]) {
        await saveProfile(data.user_profile[0]);
      }
      if (Array.isArray(data.clients)) {
        for (const c of data.clients) {
          try { await tauriInvoke('create_client', { payload: c }); } catch { /* skip duplicate */ }
        }
      }
      if (Array.isArray(data.projects)) {
        for (const p of data.projects) {
          try { await tauriInvoke('create_project', { payload: p }); } catch { /* skip duplicate */ }
        }
      }
      if (Array.isArray(data.proposals)) {
        for (const p of data.proposals) {
          try { await tauriInvoke('create_proposal', { payload: p }); } catch { /* skip duplicate */ }
        }
      }
      if (Array.isArray(data.contracts)) {
        for (const p of data.contracts) {
          try { await tauriInvoke('create_contract', { payload: p }); } catch { /* skip duplicate */ }
        }
      }
      if (Array.isArray(data.time_entries)) {
        for (const t of data.time_entries) {
          try { await tauriInvoke('create_time_entry', { payload: t }); } catch { /* skip duplicate */ }
        }
      }
      if (Array.isArray(data.invoices)) {
        for (const inv of data.invoices) {
          try {
            await tauriInvoke('create_invoice', {
              payload: { ...inv, line_items: typeof inv.line_items === 'string' ? inv.line_items : JSON.stringify(inv.line_items) },
            });
          } catch { /* skip duplicate */ }
        }
      }
      if (Array.isArray(data.expenses)) {
        for (const e of data.expenses) {
          try { await tauriInvoke('create_expense', { payload: e }); } catch { /* skip duplicate */ }
        }
      }

      addToast('Data imported successfully', 'success');
      await loadProfile();
    } catch {
      addToast('Import failed — check file format', 'error');
    }
  };

  const handleResetData = async () => {
    try {
      const { invoke: tauriInvoke } = await import('@tauri-apps/api/core');
      const tables = [
        { list: 'get_clients', name: 'clients', del: 'delete_client' },
        { list: 'get_projects', name: 'projects', del: 'delete_project' },
        { list: 'get_proposals', name: 'proposals', del: 'delete_proposal' },
        { list: 'get_contracts', name: 'contracts', del: 'delete_contract' },
        { list: 'get_time_entries', name: 'time_entries', del: 'delete_time_entry' },
        { list: 'get_invoices', name: 'invoices', del: 'delete_invoice' },
        { list: 'get_expenses', name: 'expenses', del: 'delete_expense' },
      ];
      for (const t of tables) {
        const records: { id: string }[] = await tauriInvoke(t.list);
        for (const r of records) {
          await tauriInvoke(t.del, { id: r.id });
        }
      }

      // Finally, delete the user profile itself
      await tauriInvoke('delete_user_profile');

      localStorage.clear();
      setShowResetModal(false);
      addToast('All data has been reset', 'info');

      // Reload the application to force it back to the onboarding screen
      setTimeout(() => {
        window.location.reload();
      }, 500);
